#!/usr/bin/env bash
#
# Exercises the platform end to end *through the gateway*, which is what
# CLAUDE.md section 9 asks for: a route that works when curled directly at a
# service but was never wired into YARP is a common and easy-to-miss failure.
#
# Assumes `docker compose up -d --build` has finished.
#
# **Do not edit this file while a run of it is in flight.** Bash reads a script
# incrementally rather than all at once, so an edit shifts the byte offsets
# under a running copy and it resumes mid-token - which shows up as
# "community: command not found" from the middle of a JSON literal, several
# hundred lines away from anything that was changed. It looks exactly like a
# bug in the platform and is not one. The run takes about twenty minutes; wait
# it out, or copy the script first.
#
# One domain, no Host headers: a member signs in and the token decides which
# Samaaj they belong to (root CLAUDE.md section 6).
set -euo pipefail

GATEWAY="${GATEWAY:-http://localhost:8080}"
SLUG="${SLUG:-smoke-samaj}"
SUPERADMIN="${SUPERADMIN:-superadmin@samaajconnect.local}"
SUPERADMIN_PASSWORD="${SUPERADMIN_PASSWORD:-change-me-immediately}"
MEMBER="${MEMBER:-smoke-member@example.com}"
MEMBER_PASSWORD="${MEMBER_PASSWORD:-a-long-enough-password}"

pass=0
fail=0

check() {
  local label="$1" expected="$2" actual="$3"
  if [ "$expected" = "$actual" ]; then
    echo "  ok    $label ($actual)"
    pass=$((pass + 1))
  else
    echo "  FAIL  $label (expected $expected, got $actual)"
    fail=$((fail + 1))
  fi
}

status() {
  curl -s -o /dev/null -w '%{http_code}' "$@"
}

# One scratch directory for the whole run, and exactly one trap.
#
# The upload sections write fixture bytes rather than shipping files, because
# what they check is the signature the services read - a committed .png would be
# testing that the file was still in the repository. They each had their own
# mktemp and their own `trap ... EXIT` until the second one silently replaced
# the first, which is what a second trap on the same signal does. One root here
# means a third section cannot repeat that.
SMOKE_TMP=$(mktemp -d)
trap 'rm -rf "$SMOKE_TMP"' EXIT

json_field() {
  # Deliberately grep-based: this script must run anywhere curl runs, without
  # requiring jq to be installed.
  #
  # The `|| true` matters: with `set -o pipefail`, a grep that matches nothing
  # fails the whole pipeline and errexit kills the script. That only bites on a
  # re-run, where creating an existing Samaaj returns a problem document with
  # no id - so the script died silently exactly when someone ran it twice.
  { grep -o "\"$1\":\"[^\"]*\"" || true; } | head -1 | cut -d'"' -f4
}

# Stops the run the moment an id extraction comes back empty or malformed.
#
# **This is the check the session-id bug went without.** `json_field id` was
# used on a response whose first `"id"` is the *Pathshala's*, not the session's,
# so classes were created against the wrong parent - and every check after it
# reported somebody else's service answering 404. Nothing pointed at the
# variable. A guard was added where it bit; this is the same guard everywhere
# the pattern appears, which is thirty-one places.
#
# It exits rather than counting a failure and carrying on, and that is
# deliberate. An empty id means the script is broken or the stack is, not that
# the product regressed - and continuing turns one fault into a screen of
# misleading failures pointing at innocent services. One clear line beats forty
# wrong ones.
#
# Called as a statement, never inside `$( )`: `exit` in a command substitution
# kills the subshell and the script carries on regardless, which would make this
# guard silently do nothing.
require_id() {
  local name="$1" value="$2"

  if [ -z "$value" ]; then
    echo
    echo "  FAIL  nothing extracted for '$name'."
    echo "        Every check below this point would run against an empty id -"
    echo "        which usually means a list endpoint, answering 200 for anybody."
    exit 1
  fi

  # A GUID, loosely: the services answer with these everywhere, and anything
  # else here means `json_field` matched a different field than intended.
  case "$value" in
    [0-9a-fA-F][0-9a-fA-F][0-9a-fA-F][0-9a-fA-F][0-9a-fA-F][0-9a-fA-F][0-9a-fA-F][0-9a-fA-F]-*-*-*-*)
      : ;;
    *)
      echo
      echo "  FAIL  '$name' does not look like an id: '$value'"
      echo "        json_field probably matched a different field than intended."
      exit 1
      ;;
  esac
}

wait_for_stack() {
  # The services have no healthcheck of their own (the aspnet image ships no
  # curl), so readiness is established here rather than by compose --wait.
  #
  # Waiting on the gateway alone is not enough: it comes up before the services
  # behind it have finished migrating, and the first requests then fail with a
  # 502 that looks like a routing bug. So this waits on a real route.
  local attempt=0
  until [ "$(status "$GATEWAY/health")" = "200" ] \
     && [ "$(status "$GATEWAY/v1/identity/tenants/directory")" = "200" ]; do
    attempt=$((attempt + 1))
    if [ "$attempt" -ge 90 ]; then
      echo "  FAIL  the stack did not become ready"
      exit 1
    fi
    sleep 2
  done
}

echo "Gateway smoke test against $GATEWAY"

wait_for_stack

echo
echo "Gateway itself"
check "health" 200 "$(status "$GATEWAY/health")"

# The member portal is served by the gateway at the root, so that the app and
# its API share an origin - which is what its production ApiConfig
# (`gatewayUrl: ''`) assumes. Two things have to stay true at once, and both
# have already broken once:
#
#   - the catch-all must match `/`. Written as `{**catch-all}` rather than
#     `/{**catch-all}` it matches nothing and the site is a 404.
#   - the catch-all must NOT swallow `/health` or `/v1/**`.
check "the member portal is served at the root" 200 "$(status "$GATEWAY/")"

# A client-side route. Reloading one has to reach the app, not 404 at the edge.
check "and a deep link reaches the app rather than a 404" 200 "$(status "$GATEWAY/groups")"

if curl -s "$GATEWAY/" | grep -q "<app-root"; then
  echo "  ok    and what it serves is the Angular app"
  pass=$((pass + 1))
else
  echo "  FAIL  the root did not serve the Angular app"
  fail=$((fail + 1))
fi

echo
echo "Anonymous surface"
check "unauthenticated /me is refused" 401 "$(status "$GATEWAY/v1/identity/me")"
check "the Samaaj directory is public" 200 "$(status "$GATEWAY/v1/identity/tenants/directory")"

echo
echo "Super Admin signs in"
sign_in_super_admin() {
  curl -s -X POST "$GATEWAY/v1/identity/login" \
    -H 'Content-Type: application/json' \
    -d "{\"mobileOrEmail\":\"$SUPERADMIN\",\"password\":\"$SUPERADMIN_PASSWORD\"}" \
    | json_field accessToken
}

ADMIN_TOKEN=$(sign_in_super_admin)

sign_in_as() {
  curl -s -X POST "$GATEWAY/v1/identity/login" \
    -H 'Content-Type: application/json' \
    -d "{\"mobileOrEmail\":\"$1\",\"password\":\"$2\"}" \
    | json_field accessToken
}

# Re-mints every token this script holds.
#
# **Access tokens live fifteen minutes and this run takes longer than that.**
# Several sections wait 62 seconds for the gateway's tenant-module cache to
# expire, so the wall-clock cost grows every time somebody adds a module-gated
# section - and the failure that produces is the worst kind to read: the section
# that tipped the run past the boundary passes, and every check after it fails
# with a 401, a 403, or a cascade of 404s that look like bugs in whichever
# service they happened to land on. Adding the Boli section cost twenty-one such
# failures, none of them about Boli.
#
# Called before the late sections rather than between every check, because a
# token that has just been minted is not the thing under test anywhere in
# between - the expiry behaviour itself is covered by unit tests, not here.
refresh_tokens() {
  ADMIN_TOKEN=$(sign_in_super_admin)
  MEMBER_TOKEN=$(sign_in_as "$MEMBER" "$MEMBER_PASSWORD")

  # These two exist only once the sections that create their accounts have run.
  if [ -n "${INVITE_EMAIL:-}" ]; then
    SAMAAJ_ADMIN_TOKEN=$(sign_in_as "$INVITE_EMAIL" "$MEMBER_PASSWORD")
  fi

  if [ -n "${CHILD_EMAIL:-}" ]; then
    CHILD_TOKEN=$(sign_in_as "$CHILD_EMAIL" "$CHILD_PASSWORD")
  fi
}

# The rate-limit section at the end of this script deliberately exhausts the
# credential window, so a re-run inside the following minute starts against a
# 429. Waiting it out beats failing on a condition the previous run created.
if [ -z "$ADMIN_TOKEN" ]; then
  probe=$(status -X POST "$GATEWAY/v1/identity/login" -H 'Content-Type: application/json' \
    -d "{\"mobileOrEmail\":\"$SUPERADMIN\",\"password\":\"$SUPERADMIN_PASSWORD\"}")

  if [ "$probe" = "429" ]; then
    echo "  ..    rate-limited by a previous run; waiting for the window to reset"
    sleep 62
    ADMIN_TOKEN=$(sign_in_super_admin)
  fi
fi

if [ -z "$ADMIN_TOKEN" ]; then
  echo "  FAIL  could not sign in as $SUPERADMIN through the gateway"
  exit 1
fi

echo "  ok    got a Super Admin token"
pass=$((pass + 1))

echo
echo "Super Admin creates and activates a Samaaj"
CREATE_BODY=$(curl -s -X POST "$GATEWAY/v1/identity/tenants" \
  -H 'Content-Type: application/json' -H "Authorization: Bearer $ADMIN_TOKEN" \
  -d "{\"name\":\"Smoke Samaaj\",\"slug\":\"$SLUG\",\"enabledModules\":[\"Pathshala\"]}")

TENANT_ID=$(printf '%s' "$CREATE_BODY" | json_field id)

# Empty here is expected on a re-run - creating an existing slug answers 409
# with a problem document that has no id - so the guard goes *after* the
# fallback has had its go, not before it. The one place an empty id is a normal
# state rather than a broken script.
if [ -z "$TENANT_ID" ]; then
  echo "  note  Samaaj '$SLUG' already exists; resolving it instead"
  TENANT_ID=$(curl -s "$GATEWAY/v1/identity/tenants/$SLUG" | json_field id)
else
  echo "  ok    created Samaaj $TENANT_ID"
  pass=$((pass + 1))
fi

require_id tenant_id "$TENANT_ID"

check "activate" 200 "$(status -X PATCH "$GATEWAY/v1/identity/tenants/$TENANT_ID/status" \
  -H 'Content-Type: application/json' -H "Authorization: Bearer $ADMIN_TOKEN" \
  -d '{"status":"Active"}')"

echo
echo "Consent notice, shown before anyone registers"
NOTICE_VERSION=$(curl -s "$GATEWAY/v1/identity/consent-notice" | json_field version)

if [ -n "$NOTICE_VERSION" ]; then
  echo "  ok    consent notice is public (version $NOTICE_VERSION)"
  pass=$((pass + 1))
else
  echo "  FAIL  could not read the consent notice"
  fail=$((fail + 1))
fi

check "registering without consent is refused" 400 \
  "$(status -X POST "$GATEWAY/v1/identity/register" -H 'Content-Type: application/json' \
     -d "{\"tenantSlug\":\"$SLUG\",\"fullName\":\"No Consent\",\"mobileOrEmail\":\"no-consent@example.com\",\"password\":\"$MEMBER_PASSWORD\",\"consentedPurposes\":[],\"noticeVersion\":\"$NOTICE_VERSION\"}")"

echo
echo "Member registers, choosing their Samaaj from the directory"
REGISTER_STATUS=$(status -X POST "$GATEWAY/v1/identity/register" \
  -H 'Content-Type: application/json' \
  -d "{\"tenantSlug\":\"$SLUG\",\"fullName\":\"Smoke Member\",\"mobileOrEmail\":\"$MEMBER\",\"password\":\"$MEMBER_PASSWORD\",\"consentedPurposes\":[\"Membership\"],\"noticeVersion\":\"$NOTICE_VERSION\"}")

if [ "$REGISTER_STATUS" = "409" ]; then
  echo "  note  member already registered from an earlier run"
else
  check "register" 201 "$REGISTER_STATUS"
fi

echo
echo "Member signs in and the token decides their Samaaj"
MEMBER_LOGIN=$(curl -s -X POST "$GATEWAY/v1/identity/login" \
  -H 'Content-Type: application/json' \
  -d "{\"mobileOrEmail\":\"$MEMBER\",\"password\":\"$MEMBER_PASSWORD\"}")

MEMBER_TOKEN=$(printf '%s' "$MEMBER_LOGIN" | json_field accessToken)
RESOLVED_SLUG=$(printf '%s' "$MEMBER_LOGIN" | json_field tenantSlug)

if [ -z "$MEMBER_TOKEN" ]; then
  echo "  FAIL  member could not sign in through the gateway"
  fail=$((fail + 1))
else
  echo "  ok    got a member token"
  pass=$((pass + 1))
fi

check "login resolved the Samaaj without being told" "$SLUG" "$RESOLVED_SLUG"

echo
echo "Routing to each service"
check "identity /me" 200 "$(status -H "Authorization: Bearer $MEMBER_TOKEN" \
  "$GATEWAY/v1/identity/me")"

check "audit log is refused to a member" 403 "$(status -H "Authorization: Bearer $MEMBER_TOKEN" \
  "$GATEWAY/v1/audit/logs")"

check "audit log is served to a Super Admin overriding into the Samaaj" 200 \
  "$(status -H "Authorization: Bearer $ADMIN_TOKEN" \
     -H "X-Tenant-Override-Id: $TENANT_ID" "$GATEWAY/v1/audit/logs")"

check "notifications" 200 "$(status -H "Authorization: Bearer $MEMBER_TOKEN" \
  "$GATEWAY/v1/notifications")"

echo
echo "Member profile, created by the registration event rather than by a call"
profile_ready=0
for attempt in $(seq 1 30); do
  if [ "$(status -H "Authorization: Bearer $MEMBER_TOKEN" "$GATEWAY/v1/members/me")" = "200" ]; then
    profile_ready=1
    break
  fi
  sleep 2
done
check "profile arrives over Kafka" 1 "$profile_ready"

check "member directory" 200 "$(status -H "Authorization: Bearer $MEMBER_TOKEN" \
  "$GATEWAY/v1/members")"

# Either answer is correct: 404 on a clean database, 200 on a re-run, because
# the conversion section below gives this member a family.
FAMILY_LOOKUP=$(status -H "Authorization: Bearer $MEMBER_TOKEN" "$GATEWAY/v1/families/mine")

if [ "$FAMILY_LOOKUP" = "404" ] || [ "$FAMILY_LOOKUP" = "200" ]; then
  echo "  ok    family lookup routes ($FAMILY_LOOKUP)"
  pass=$((pass + 1))
else
  echo "  FAIL  family lookup routes (got $FAMILY_LOOKUP)"
  fail=$((fail + 1))
fi

check "children of a member with no family" 200 "$(status -H "Authorization: Bearer $MEMBER_TOKEN" \
  "$GATEWAY/v1/children")"

check "conversion queue is refused to a member" 403 "$(status -H "Authorization: Bearer $MEMBER_TOKEN" \
  "$GATEWAY/v1/children/conversion-requests")"

echo
echo "The profile screen's endpoint, and taking yourself out of the directory"

MEMBER_ID=$(curl -s -H "Authorization: Bearer $MEMBER_TOKEN" "$GATEWAY/v1/members/me" | json_field id)
require_id member_id "$MEMBER_ID"

profile_body() {
  # $1 is the isListedInDirectory value, or "omit" to leave it out entirely.
  local listed="$1"
  local listing=",\"isListedInDirectory\":$listed"

  [ "$listed" = "omit" ] && listing=""

  printf '{"fullName":"Smoke Member","gender":"Male","mobile":"+919812345678","locality":"Udaipur","privacy":{"mobile":"SamaajOnly","email":"Private","address":"Private","profession":"SamaajOnly","dateOfBirth":"Private"}%s}' "$listing"
}

check "a member edits their own profile" 200 \
  "$(status -X PATCH "$GATEWAY/v1/members/$MEMBER_ID" -H 'Content-Type: application/json' \
     -H "Authorization: Bearer $MEMBER_TOKEN" -d "$(profile_body true)")"

# Not defaulted to true. A client that does not know about the field would
# otherwise put a member who had opted out back into the directory, silently,
# because they edited their address.
check "an update that omits the directory setting is refused" 400 \
  "$(status -X PATCH "$GATEWAY/v1/members/$MEMBER_ID" -H 'Content-Type: application/json' \
     -H "Authorization: Bearer $MEMBER_TOKEN" -d "$(profile_body omit)")"

check "and taking themselves out of the directory" 200 \
  "$(status -X PATCH "$GATEWAY/v1/members/$MEMBER_ID" -H 'Content-Type: application/json' \
     -H "Authorization: Bearer $MEMBER_TOKEN" -d "$(profile_body false)")"

if curl -s -H "Authorization: Bearer $MEMBER_TOKEN" "$GATEWAY/v1/members" \
   | grep -q "$MEMBER_ID"; then
  echo "  FAIL  an unlisted member is still in the directory"
  fail=$((fail + 1))
else
  echo "  ok    they are gone from the directory search"
  pass=$((pass + 1))
fi

# Unlisted, not unreachable. A group president has to see who applied and a post
# has an author; if this 404'd, those would break.
check "but still reachable by id" 200 \
  "$(status -H "Authorization: Bearer $MEMBER_TOKEN" "$GATEWAY/v1/members/$MEMBER_ID")"

if curl -s -H "Authorization: Bearer $ADMIN_TOKEN" -H "X-Tenant-Override-Id: $TENANT_ID" \
   "$GATEWAY/v1/members" | grep -q "$MEMBER_ID"; then
  echo "  ok    and an administrator still finds them"
  pass=$((pass + 1))
else
  echo "  FAIL  an administrator cannot find an unlisted member"
  fail=$((fail + 1))
fi


# ---- Photos the platform hosts ------------------------------------------------
#
# A profile photo used to be a URL a member typed, which meant every viewer of
# the directory fetched it from whatever host it named. The platform stores the
# bytes now and serves them itself, so nothing outside the Samaaj is asked for
# anything - and on a child's record that is the third-party tracking DPDP
# s.9(3) prohibits.
#
# The files here are written as raw bytes rather than shipped as fixtures,
# because what is being checked is the signature the service reads. A committed
# .png would be testing that the file was still in the repository.
PHOTO_DIR="$SMOKE_TMP/photos"
mkdir -p "$PHOTO_DIR"

printf '\211PNG\r\n\032\n\001\002\003\004\005\006\007\010' > "$PHOTO_DIR/photo.png"
printf '<svg xmlns="http://www.w3.org/2000/svg"><script>alert(1)</script></svg>' \
  > "$PHOTO_DIR/nasty.svg"

check "a member uploads their own photo" 200 \
  "$(status -X POST "$GATEWAY/v1/members/$MEMBER_ID/photo" \
     -H "Authorization: Bearer $MEMBER_TOKEN" -F "file=@$PHOTO_DIR/photo.png")"

# The type comes out of the bytes, not out of the part header - the header is a
# string the uploader chose.
PHOTO_TYPE=$(curl -s -o /dev/null -w '%{content_type}' \
  -H "Authorization: Bearer $MEMBER_TOKEN" "$GATEWAY/v1/members/$MEMBER_ID/photo")

if [ "${PHOTO_TYPE%%;*}" = "image/png" ]; then
  echo "  ok    and it comes back as the type read from its bytes"
  pass=$((pass + 1))
else
  echo "  FAIL  the photo came back as '$PHOTO_TYPE'"
  fail=$((fail + 1))
fi

# An SVG is a document that can carry script, and this is served from the
# platform's own origin - accepting one would close the tracking hole and open a
# stored-scripting one in its place.
#
# No `;type=image/png` on the -F argument, and that is not an oversight: curl
# answers 000 for that form here rather than sending anything, so the check
# would have failed for a reason that has nothing to do with SVGs. The claim it
# was meant to make - that the declared type is ignored - is made by the JPEG
# check below instead, which is a stronger version of it anyway.
check "an SVG is refused" 400 \
  "$(status -X POST "$GATEWAY/v1/members/$MEMBER_ID/photo" \
     -H "Authorization: Bearer $MEMBER_TOKEN" \
     -F "file=@$PHOTO_DIR/nasty.svg")"

# JPEG bytes under a .png name. The type served back is read from the bytes, so
# the name and whatever header accompanied it decide nothing.
printf '\377\330\377\340\000\020JFIF\000\001' > "$PHOTO_DIR/actually-a-jpeg.png"

curl -s -o /dev/null -X POST "$GATEWAY/v1/members/$MEMBER_ID/photo" \
  -H "Authorization: Bearer $MEMBER_TOKEN" -F "file=@$PHOTO_DIR/actually-a-jpeg.png"

DISGUISED_TYPE=$(curl -s -o /dev/null -w '%{content_type}' \
  -H "Authorization: Bearer $MEMBER_TOKEN" "$GATEWAY/v1/members/$MEMBER_ID/photo")

if [ "${DISGUISED_TYPE%%;*}" = "image/jpeg" ]; then
  echo "  ok    and a JPEG named .png is still served as a JPEG"
  pass=$((pass + 1))
else
  echo "  FAIL  a disguised JPEG came back as '$DISGUISED_TYPE'"
  fail=$((fail + 1))
fi

# The directory hands out a path on this platform rather than a foreign host.
if curl -s -H "Authorization: Bearer $MEMBER_TOKEN" "$GATEWAY/v1/members/me" \
   | grep -q "\"photoUrl\":\"/v1/members/$MEMBER_ID/photo\""; then
  echo "  ok    and the profile points at this platform, not somebody else's host"
  pass=$((pass + 1))
else
  echo "  FAIL  the profile's photoUrl is not a path on this platform"
  fail=$((fail + 1))
fi

# There is deliberately no "another member cannot replace it" check here, and
# the reason is worth writing down rather than leaving as an omission.
# CHILD_TOKEN is the only second member this script has, and it is not signed in
# until the conversion section further down - so a check here would send an
# empty bearer, get 401 rather than the 403 it was written for, and pass or fail
# for a reason that has nothing to do with photos. HostedPhotoTests covers that
# rule against two real members, in both directions, and cross-tenant besides.

check "an anonymous caller cannot fetch it at all" 401 \
  "$(status "$GATEWAY/v1/members/$MEMBER_ID/photo")"

check "the member takes their photo down" 200 \
  "$(status -X DELETE "$GATEWAY/v1/members/$MEMBER_ID/photo" \
     -H "Authorization: Bearer $MEMBER_TOKEN")"

check "and doing it twice is still success" 200 \
  "$(status -X DELETE "$GATEWAY/v1/members/$MEMBER_ID/photo" \
     -H "Authorization: Bearer $MEMBER_TOKEN")"

check "after which there is no photo to fetch" 404 \
  "$(status -H "Authorization: Bearer $MEMBER_TOKEN" "$GATEWAY/v1/members/$MEMBER_ID/photo")"
check "back into the directory" 200 \
  "$(status -X PATCH "$GATEWAY/v1/members/$MEMBER_ID" -H 'Content-Type: application/json' \
     -H "Authorization: Bearer $MEMBER_TOKEN" -d "$(profile_body true)")"


echo
echo "Adult-child conversion, end to end across three services"

# A fresh identifier per run: the flow creates a real account, and re-running
# must not collide with the one the last run made.
CHILD_EMAIL="converted-$(date +%s)@example.com"
CHILD_PASSWORD="a-long-enough-password"
ADMIN_TENANT_HEADER="X-Tenant-Override-Id: $TENANT_ID"

# The member may already head a family from an earlier run.
FAMILY_STATUS=$(status -X POST "$GATEWAY/v1/families" -H "Authorization: Bearer $MEMBER_TOKEN")

if [ "$FAMILY_STATUS" = "201" ] || [ "$FAMILY_STATUS" = "409" ]; then
  echo "  ok    member heads a family ($FAMILY_STATUS)"
  pass=$((pass + 1))
else
  echo "  FAIL  member heads a family (got $FAMILY_STATUS)"
  fail=$((fail + 1))
fi

DOB=$(date -d '20 years ago' +%Y-%m-%d 2>/dev/null || date -v-20y +%Y-%m-%d)

CHILD_NOTICE=$(curl -s -H "Authorization: Bearer $MEMBER_TOKEN" \
  "$GATEWAY/v1/children/data-notice" | json_field version)

check "the child data notice is available before asking" 200 \
  "$(status -H "Authorization: Bearer $MEMBER_TOKEN" "$GATEWAY/v1/children/data-notice")"

check "a child cannot be added without parental consent" 400 \
  "$(status -X POST "$GATEWAY/v1/children" -H 'Content-Type: application/json' \
     -H "Authorization: Bearer $MEMBER_TOKEN" \
     -d "{\"fullName\":\"No Consent\",\"dateOfBirth\":\"$DOB\",\"gender\":\"Male\",\"parentalConsentGiven\":false,\"noticeVersion\":\"$CHILD_NOTICE\"}")"

CHILD_ID=$(curl -s -X POST "$GATEWAY/v1/children" \
  -H 'Content-Type: application/json' -H "Authorization: Bearer $MEMBER_TOKEN" \
  -d "{\"fullName\":\"Aarav Jain\",\"dateOfBirth\":\"$DOB\",\"gender\":\"Male\",\"parentalConsentGiven\":true,\"noticeVersion\":\"$CHILD_NOTICE\"}" | json_field id)

if [ -n "$CHILD_ID" ]; then
  echo "  ok    added a child who has turned 18"
  pass=$((pass + 1))
else
  echo "  FAIL  could not add a child"
  fail=$((fail + 1))
fi

# The Pathshala placement queue holds child ids and no names, so an
# administrator resolves them here. Names only: the full child record carries a
# date of birth and the parental-consent record, and a queue printing a name has
# no business receiving those.
if curl -s -H "Authorization: Bearer $ADMIN_TOKEN" -H "$ADMIN_TENANT_HEADER" \
   "$GATEWAY/v1/children/names?ids=$CHILD_ID" | grep -q '"fullName":"Aarav Jain"'; then
  echo "  ok    an administrator can put a name to a child id"
  pass=$((pass + 1))
else
  echo "  FAIL  the child-name lookup did not answer"
  fail=$((fail + 1))
fi

if curl -s -H "Authorization: Bearer $ADMIN_TOKEN" -H "$ADMIN_TENANT_HEADER" \
   "$GATEWAY/v1/children/names?ids=$CHILD_ID" | grep -qE '"dateOfBirth"|"parentalConsent"'; then
  echo "  FAIL  the child-name lookup returned more than a name"
  fail=$((fail + 1))
else
  echo "  ok    and gets a name and nothing else"
  pass=$((pass + 1))
fi

check "a member cannot name children by id" 403 \
  "$(status -H "Authorization: Bearer $MEMBER_TOKEN" "$GATEWAY/v1/children/names?ids=$CHILD_ID")"

REQUEST_ID=$(curl -s -X POST "$GATEWAY/v1/children/$CHILD_ID/conversion" \
  -H 'Content-Type: application/json' -H "Authorization: Bearer $MEMBER_TOKEN" \
  -d "{\"mobileOrEmail\":\"$CHILD_EMAIL\"}" | json_field id)

if [ -n "$REQUEST_ID" ]; then
  echo "  ok    family head requested conversion"
  pass=$((pass + 1))
else
  echo "  FAIL  could not request conversion"
  fail=$((fail + 1))
fi

check "the head cannot approve their own request" 403 \
  "$(status -X POST "$GATEWAY/v1/children/conversion-requests/$REQUEST_ID/decide" \
     -H 'Content-Type: application/json' -H "Authorization: Bearer $MEMBER_TOKEN" \
     -d '{"approve":true}')"

check "a Samaaj admin approves it" 200 \
  "$(status -X POST "$GATEWAY/v1/children/conversion-requests/$REQUEST_ID/decide" \
     -H 'Content-Type: application/json' -H "Authorization: Bearer $ADMIN_TOKEN" \
     -H "$ADMIN_TENANT_HEADER" -d '{"approve":true,"note":"Verified in person"}')"

# identity-tenant-service consumes the approval and creates the account.
NEW_USER_ID=""
for attempt in $(seq 1 30); do
  NEW_USER_ID=$(curl -s -H "Authorization: Bearer $ADMIN_TOKEN" -H "$ADMIN_TENANT_HEADER" \
    "$GATEWAY/v1/identity/activations/pending" \
    | tr '}' '\n' | { grep "$CHILD_EMAIL" || true; } | json_field userId)

  [ -n "$NEW_USER_ID" ] && break
  sleep 2
done

if [ -n "$NEW_USER_ID" ]; then
  echo "  ok    identity created the account over Kafka, awaiting activation"
  pass=$((pass + 1))
else
  echo "  FAIL  the account never appeared on the pending list"
  fail=$((fail + 1))
fi

ACTIVATION_CODE=$(curl -s -X POST "$GATEWAY/v1/identity/activations/$NEW_USER_ID/code" \
  -H "Authorization: Bearer $ADMIN_TOKEN" -H "$ADMIN_TENANT_HEADER" | json_field code)

if [ -n "$ACTIVATION_CODE" ]; then
  echo "  ok    admin issued a one-time activation code"
  pass=$((pass + 1))
else
  echo "  FAIL  could not issue an activation code"
  fail=$((fail + 1))
fi

check "the new member redeems it and sets a password" 200 \
  "$(status -X POST "$GATEWAY/v1/identity/activations/redeem" -H 'Content-Type: application/json' \
     -d "{\"mobileOrEmail\":\"$CHILD_EMAIL\",\"code\":\"$ACTIVATION_CODE\",\"password\":\"$CHILD_PASSWORD\"}")"

check "the code cannot be redeemed twice" 403 \
  "$(status -X POST "$GATEWAY/v1/identity/activations/redeem" -H 'Content-Type: application/json' \
     -d "{\"mobileOrEmail\":\"$CHILD_EMAIL\",\"code\":\"$ACTIVATION_CODE\",\"password\":\"$CHILD_PASSWORD\"}")"

check "the converted child can now sign in" 200 \
  "$(status -X POST "$GATEWAY/v1/identity/login" -H 'Content-Type: application/json' \
     -d "{\"mobileOrEmail\":\"$CHILD_EMAIL\",\"password\":\"$CHILD_PASSWORD\"}")"

# member-family consumes the activation and closes the loop.
converted=0
for attempt in $(seq 1 30); do
  if curl -s -H "Authorization: Bearer $MEMBER_TOKEN" "$GATEWAY/v1/children" \
     | tr '}' '\n' | grep -q '"status":"Converted"'; then
    converted=1
    break
  fi
  sleep 2
done
check "the child record is marked Converted" 1 "$converted"
echo
echo "DPDP: the three data exports, and the grievance contact"
check "identity export" 200 "$(status -H "Authorization: Bearer $MEMBER_TOKEN" \
  "$GATEWAY/v1/identity/me/data-export")"

check "member-family export" 200 "$(status -H "Authorization: Bearer $MEMBER_TOKEN" \
  "$GATEWAY/v1/members/me/data-export")"

check "audit export" 200 "$(status -H "Authorization: Bearer $MEMBER_TOKEN" \
  "$GATEWAY/v1/audit/me/data-export")"

check "withdrawing an optional consent" 200 \
  "$(status -X POST "$GATEWAY/v1/identity/me/consents/Communications/withdraw" \
     -H "Authorization: Bearer $MEMBER_TOKEN")"

check "the membership consent cannot be withdrawn piecemeal" 409 \
  "$(status -X POST "$GATEWAY/v1/identity/me/consents/Membership/withdraw" \
     -H "Authorization: Bearer $MEMBER_TOKEN")"

check "naming the grievance contact" 200 \
  "$(status -X PUT "$GATEWAY/v1/identity/tenants/$TENANT_ID/grievance-contact" \
     -H 'Content-Type: application/json' -H "Authorization: Bearer $ADMIN_TOKEN" \
     -H "$ADMIN_TENANT_HEADER" \
     -d '{"name":"Ravi Shah","email":"grievances@example.com","phone":null}')"

GRIEVANCE=$(curl -s "$GATEWAY/v1/identity/tenants/$SLUG" | json_field email)
check "it is published to anyone, as section 13 requires" "grievances@example.com" "$GRIEVANCE"

# ---- The Samaaj's logo --------------------------------------------------------
#
# `LogoUrl` had been on the record since the first migration with nothing able
# to set it - no command took one - beside an "Upload Logo" control the admin
# wireframe drew with nothing behind it.
#
# The logo is the one image on this platform served to anyone, and this section
# checks that on purpose rather than by omission: the registration form asks
# somebody to pick their Samaaj before they have a token, so a logo needing one
# could not appear beside the name.
LOGO_DIR="$SMOKE_TMP/logos"
mkdir -p "$LOGO_DIR"

printf '\211PNG\r\n\032\n\001\002\003\004\005\006\007\010' > "$LOGO_DIR/logo.png"

check "a Super Admin uploads the Samaaj's logo" 200 \
  "$(status -X POST "$GATEWAY/v1/identity/tenants/$TENANT_ID/logo" \
     -H "Authorization: Bearer $ADMIN_TOKEN" -H "$ADMIN_TENANT_HEADER" \
     -F "file=@$LOGO_DIR/logo.png")"

check "and anybody at all may fetch it, with no token" 200 \
  "$(status "$GATEWAY/v1/identity/tenants/$TENANT_ID/logo")"

LOGO_TYPE=$(curl -s -o /dev/null -w '%{content_type}' \
  "$GATEWAY/v1/identity/tenants/$TENANT_ID/logo")

if [ "${LOGO_TYPE%%;*}" = "image/png" ]; then
  echo "  ok    served as the type read from its bytes"
  pass=$((pass + 1))
else
  echo "  FAIL  the logo came back as '$LOGO_TYPE'"
  fail=$((fail + 1))
fi

# Reading is anonymous; writing is not, and the two share a path.
check "a member cannot set it" 403 \
  "$(status -X POST "$GATEWAY/v1/identity/tenants/$TENANT_ID/logo" \
     -H "Authorization: Bearer $MEMBER_TOKEN" -F "file=@$LOGO_DIR/logo.png")"

check "nor can an anonymous caller" 401 \
  "$(status -X POST "$GATEWAY/v1/identity/tenants/$TENANT_ID/logo" \
     -F "file=@$LOGO_DIR/logo.png")"

# The public directory hands out a path on this platform. This is what the
# registration form reads.
if curl -s "$GATEWAY/v1/identity/tenants/$SLUG" \
   | grep -q "\"logoUrl\":\"/v1/identity/tenants/$TENANT_ID/logo\""; then
  echo "  ok    and the public Samaaj directory points at it"
  pass=$((pass + 1))
else
  echo "  FAIL  the directory's logoUrl is not a path on this platform"
  fail=$((fail + 1))
fi

check "taking it down" 200 \
  "$(status -X DELETE "$GATEWAY/v1/identity/tenants/$TENANT_ID/logo" \
     -H "Authorization: Bearer $ADMIN_TOKEN" -H "$ADMIN_TENANT_HEADER")"

check "and doing it twice is still success" 200 \
  "$(status -X DELETE "$GATEWAY/v1/identity/tenants/$TENANT_ID/logo" \
     -H "Authorization: Bearer $ADMIN_TOKEN" -H "$ADMIN_TENANT_HEADER")"

check "after which there is no logo to fetch" 404 \
  "$(status "$GATEWAY/v1/identity/tenants/$TENANT_ID/logo")"

echo

echo

echo
echo "Admin surface: tenants, modules, the role matrix, and administrators"

check "the tenant list is refused to a member" 403 \
  "$(status -H "Authorization: Bearer $MEMBER_TOKEN" "$GATEWAY/v1/identity/tenants")"

check "the tenant list is served to a Super Admin" 200 \
  "$(status -H "Authorization: Bearer $ADMIN_TOKEN" "$GATEWAY/v1/identity/tenants")"

# The admin panel signs an admin out if /me fails, so this being right is the
# difference between an unusable panel and a working one.
check "a Super Admin overriding into a Samaaj can still read their own account" 200 \
  "$(status -H "Authorization: Bearer $ADMIN_TOKEN" -H "$ADMIN_TENANT_HEADER" \
     "$GATEWAY/v1/identity/me")"

OVERRIDDEN_ME=$(curl -s -H "Authorization: Bearer $ADMIN_TOKEN" -H "$ADMIN_TENANT_HEADER" \
  "$GATEWAY/v1/identity/me" | json_field tenantId)

if [ "$OVERRIDDEN_ME" = "00000000-0000-0000-0000-000000000000" ]; then
  echo "  ok    and is still themselves, not somebody in the Samaaj they administer"
  pass=$((pass + 1))
else
  echo "  FAIL  the override changed who /me says the caller is (got $OVERRIDDEN_ME)"
  fail=$((fail + 1))
fi

check "a nonsense status is refused, not answered with an empty list" 400 \
  "$(status -H "Authorization: Bearer $ADMIN_TOKEN" "$GATEWAY/v1/identity/tenants?status=Dormant")"

check "the module catalogue is public because it fills a form" 200 \
  "$(status "$GATEWAY/v1/identity/tenants/modules")"

check "a mistyped module key is refused" 400 \
  "$(status -X PUT "$GATEWAY/v1/identity/tenants/$TENANT_ID/modules" \
     -H 'Content-Type: application/json' -H "Authorization: Bearer $ADMIN_TOKEN" \
     -d '{"enabledModules":["pathshaala"]}')"

check "modules are replaced as a whole set" 200 \
  "$(status -X PUT "$GATEWAY/v1/identity/tenants/$TENANT_ID/modules" \
     -H 'Content-Type: application/json' -H "Authorization: Bearer $ADMIN_TOKEN" \
     -d '{"enabledModules":["pathshala","boli"]}')"

check "the role matrix is readable by any signed-in member" 200 \
  "$(status -H "Authorization: Bearer $MEMBER_TOKEN" "$GATEWAY/v1/identity/roles")"

MATRIX=$(curl -s -H "Authorization: Bearer $MEMBER_TOKEN" "$GATEWAY/v1/identity/roles")

if printf '%s' "$MATRIX" | grep -q '"editable":false'; then
  echo "  ok    the matrix says it is not editable rather than letting a screen assume"
  pass=$((pass + 1))
else
  echo "  FAIL  the matrix says it is not editable"
  fail=$((fail + 1))
fi

INVITE_EMAIL="admin-$(date +%s)@example.com"

check "a member cannot invite an administrator" 403 \
  "$(status -X POST "$GATEWAY/v1/identity/admins" -H 'Content-Type: application/json' \
     -H "Authorization: Bearer $MEMBER_TOKEN" \
     -d "{\"fullName\":\"Rajesh Jain\",\"mobileOrEmail\":\"$INVITE_EMAIL\",\"roles\":[\"SamaajAdmin\"]}")"

check "SuperAdmin cannot be invited into" 400 \
  "$(status -X POST "$GATEWAY/v1/identity/admins" -H 'Content-Type: application/json' \
     -H "Authorization: Bearer $ADMIN_TOKEN" -H "$ADMIN_TENANT_HEADER" \
     -d "{\"fullName\":\"Rajesh Jain\",\"mobileOrEmail\":\"$INVITE_EMAIL\",\"roles\":[\"SuperAdmin\"]}")"

INVITE=$(curl -s -X POST "$GATEWAY/v1/identity/admins" -H 'Content-Type: application/json' \
  -H "Authorization: Bearer $ADMIN_TOKEN" -H "$ADMIN_TENANT_HEADER" \
  -d "{\"fullName\":\"Rajesh Jain\",\"mobileOrEmail\":\"$INVITE_EMAIL\",\"roles\":[\"SamaajAdmin\"]}")

INVITED_ID=$(printf '%s' "$INVITE" | json_field userId)
INVITE_CODE=$(printf '%s' "$INVITE" | json_field activationCode)

if [ -n "$INVITED_ID" ] && [ -n "$INVITE_CODE" ]; then
  echo "  ok    an admin is invited and handed a one-time code"
  pass=$((pass + 1))
else
  echo "  FAIL  an admin is invited and handed a one-time code ($INVITE)"
  fail=$((fail + 1))
fi

check "the invited account cannot be signed into until the code is redeemed" 401 \
  "$(status -X POST "$GATEWAY/v1/identity/login" -H 'Content-Type: application/json' \
     -d "{\"mobileOrEmail\":\"$INVITE_EMAIL\",\"password\":\"$MEMBER_PASSWORD\"}")"

check "the same identifier cannot be invited twice" 409 \
  "$(status -X POST "$GATEWAY/v1/identity/admins" -H 'Content-Type: application/json' \
     -H "Authorization: Bearer $ADMIN_TOKEN" -H "$ADMIN_TENANT_HEADER" \
     -d "{\"fullName\":\"Rajesh Jain\",\"mobileOrEmail\":\"$INVITE_EMAIL\",\"roles\":[\"SamaajAdmin\"]}")"

check "the invited admin redeems the code and sets a password" 200 \
  "$(status -X POST "$GATEWAY/v1/identity/activations/redeem" -H 'Content-Type: application/json' \
     -d "{\"mobileOrEmail\":\"$INVITE_EMAIL\",\"code\":\"$INVITE_CODE\",\"password\":\"$MEMBER_PASSWORD\"}")"

SAMAAJ_ADMIN_TOKEN=$(curl -s -X POST "$GATEWAY/v1/identity/login" \
  -H 'Content-Type: application/json' \
  -d "{\"mobileOrEmail\":\"$INVITE_EMAIL\",\"password\":\"$MEMBER_PASSWORD\"}" | json_field accessToken)

if [ -n "$SAMAAJ_ADMIN_TOKEN" ]; then
  echo "  ok    the invited admin signs in with the role they were invited into"
  pass=$((pass + 1))
else
  echo "  FAIL  the invited admin signs in"
  fail=$((fail + 1))
fi

# Editing the matrix, through the gateway.
#
# This is the endpoint that changes what a role may do for everybody who holds
# it, now and in future - and it reached the platform absent from three
# hand-written lists at once: no row in identity-tenant-service's own Commands
# table, no line in API-CONTRACTS.md (which still described /roles as
# "Read-only"), and no call here. It has eleven integration tests and had never
# been through the gateway. `scripts/service-docs.sh` is what found it.
#
# **The Samaaj administrator, not ADMIN_TOKEN**, which is the platform Super
# Admin. The matrix is edited per Samaaj, so a Super Admin who has not chosen
# one is refused with `Matrix.NoSamaaj` - and the first version of this block
# sat higher up the file using ADMIN_TOKEN and answered 403 to everything,
# including the two floors, which happen to be 403 and 409. A block placed
# before the identity it needs exists does not fail for the reason it looks
# like it failed. It lives here because this is where SAMAAJ_ADMIN_TOKEN does.
#
# PathshalaStudent is the role used because no account in this run holds one, so
# a change to it cannot alter what any later section is allowed to do. The grant
# is put back at the end regardless.
STUDENT_ROLE=a0000000-0000-0000-0000-000000000007
SUPERADMIN_ROLE=a0000000-0000-0000-0000-000000000001
SAMAAJADMIN_ROLE=a0000000-0000-0000-0000-000000000002

check "an administrator can grant a role a permission it never had" 200 \
  "$(status -X PUT "$GATEWAY/v1/identity/roles/$STUDENT_ROLE/permissions/Timeline.Moderate" \
     -H 'Content-Type: application/json' -H "Authorization: Bearer $SAMAAJ_ADMIN_TOKEN" \
     -d '{"granted":true}')"

# One line per role, so a grep for a permission answers about *that* role.
#
# The first version of this grepped the whole document for "Timeline.Moderate",
# which ContentModerator holds by default - so it would have reported the grant
# as landing no matter what the endpoint did. Splitting on the role boundary is
# what makes the check about the row it names. Permissions are plain strings in
# this response, so a role object contains no second `{"id":`.
student_row() {
  curl -s -H "Authorization: Bearer $SAMAAJ_ADMIN_TOKEN" "$GATEWAY/v1/identity/roles" \
    | sed 's/{"id":/\n{"id":/g' \
    | { grep '"name":"PathshalaStudent"' || true; }
}

if student_row | grep -q '"Timeline.Moderate"'; then
  echo "  ok    and the change is on the matrix the next read returns"
  pass=$((pass + 1))
else
  echo "  FAIL  the change is on the matrix the next read returns"
  fail=$((fail + 1))
fi

check "a member without Roles.Manage cannot edit it" 403 \
  "$(status -X PUT "$GATEWAY/v1/identity/roles/$STUDENT_ROLE/permissions/Timeline.Moderate" \
     -H 'Content-Type: application/json' -H "Authorization: Bearer $MEMBER_TOKEN" \
     -d '{"granted":false}')"

check "SuperAdmin is platform administration and no Samaaj may edit it" 403 \
  "$(status -X PUT "$GATEWAY/v1/identity/roles/$SUPERADMIN_ROLE/permissions/Timeline.Moderate" \
     -H 'Content-Type: application/json' -H "Authorization: Bearer $SAMAAJ_ADMIN_TOKEN" \
     -d '{"granted":false}')"

check "and a Samaaj cannot take Roles.Manage off its own administrators" 409 \
  "$(status -X PUT "$GATEWAY/v1/identity/roles/$SAMAAJADMIN_ROLE/permissions/Roles.Manage" \
     -H 'Content-Type: application/json' -H "Authorization: Bearer $SAMAAJ_ADMIN_TOKEN" \
     -d '{"granted":false}')"

check "granting it back is allowed, because only removal locks anybody out" 200 \
  "$(status -X PUT "$GATEWAY/v1/identity/roles/$SAMAAJADMIN_ROLE/permissions/Roles.Manage" \
     -H 'Content-Type: application/json' -H "Authorization: Bearer $SAMAAJ_ADMIN_TOKEN" \
     -d '{"granted":true}')"

check "and the grant this section made is put back" 200 \
  "$(status -X PUT "$GATEWAY/v1/identity/roles/$STUDENT_ROLE/permissions/Timeline.Moderate" \
     -H 'Content-Type: application/json' -H "Authorization: Bearer $SAMAAJ_ADMIN_TOKEN" \
     -d '{"granted":false}')"

# The other half of the read-back, and the reason the pair is worth more than
# either alone: if `student_row` were selecting the whole document rather than
# one role, the check above would pass and this one could not.
if student_row | grep -q '"Timeline.Moderate"'; then
  echo "  FAIL  the role is back to its default permissions"
  fail=$((fail + 1))
else
  echo "  ok    leaving the role back at its default permissions"
  pass=$((pass + 1))
fi

# ---- Taking back a join request ------------------------------------------------
#
# A pending request counts as belonging to a household, deliberately - otherwise
# somebody could ask two families at once and both heads could accept. Nothing
# could cancel one, so a head who never answered left that member unable to join
# anywhere else or create their own, indefinitely, with no way out that did not
# run through somebody else.
#
# **A registered member, not the invited administrator.** The first version of
# this block used SAMAAJ_ADMIN_TOKEN and every check answered 404: an invited
# admin account is created by invitation, which does not publish
# `identity.user.registered.v1`, so member-family-service has no profile for
# them and they are not a member of anything. Three checks failed for a reason
# that had nothing to do with withdrawing.
JOIN_STAMP="$(date +%s)"
JOIN_EMAIL="joiner-$JOIN_STAMP@example.com"

check "a second member registers" 201 \
  "$(status -X POST "$GATEWAY/v1/identity/register" -H 'Content-Type: application/json' \
     -d "{\"tenantSlug\":\"$SLUG\",\"fullName\":\"Joiner $JOIN_STAMP\",\"mobileOrEmail\":\"$JOIN_EMAIL\",\"password\":\"$MEMBER_PASSWORD\",\"consentedPurposes\":[\"Membership\"],\"noticeVersion\":\"$NOTICE_VERSION\"}")"

JOIN_TOKEN=$(curl -s -X POST "$GATEWAY/v1/identity/login" -H 'Content-Type: application/json' \
  -d "{\"mobileOrEmail\":\"$JOIN_EMAIL\",\"password\":\"$MEMBER_PASSWORD\"}" | json_field accessToken)

# Not require_id: that guard is for GUIDs, and a JWT is not one - it aborted
# the whole run on its first outing. The same is true of a family code.
if [ -z "$JOIN_TOKEN" ]; then
  echo "  FAIL  the second member could not sign in"
  fail=$((fail + 1))
  exit 1
fi

# Their profile is created by a consumer, so it is not there the instant
# registration returns. Everything below needs it.
joiner_profile=0
for attempt in $(seq 1 30); do
  if [ "$(status -H "Authorization: Bearer $JOIN_TOKEN" "$GATEWAY/v1/members/me")" = "200" ]; then
    joiner_profile=1
    break
  fi
  sleep 2
done
check "and their profile arrives over Kafka" 1 "$joiner_profile"

FAMILY_CODE=$(curl -s -H "Authorization: Bearer $MEMBER_TOKEN" \
  "$GATEWAY/v1/families/mine" | json_field familyCode)

if [ -z "$FAMILY_CODE" ]; then
  echo "  FAIL  no family code came back for the head"
  fail=$((fail + 1))
  exit 1
fi

check "withdrawing with nothing pending is success" 200 \
  "$(status -X DELETE "$GATEWAY/v1/families/join-requests/mine" \
     -H "Authorization: Bearer $JOIN_TOKEN")"

check "they ask to join the head's household" 200 \
  "$(status -X POST "$GATEWAY/v1/families/join-requests" \
     -H 'Content-Type: application/json' -H "Authorization: Bearer $JOIN_TOKEN" \
     -d "{\"familyCode\":\"$FAMILY_CODE\",\"relationship\":\"Sibling\"}")"

# The dead end: one standing request and they cannot start a household either.
check "and while it stands they cannot create their own household" 409 \
  "$(status -X POST "$GATEWAY/v1/families" -H "Authorization: Bearer $JOIN_TOKEN")"

check "they take the request back themselves" 200 \
  "$(status -X DELETE "$GATEWAY/v1/families/join-requests/mine" \
     -H "Authorization: Bearer $JOIN_TOKEN")"

# 201 rather than 409 is what proves the request is gone rather than hidden.
check "after which they can" 201 \
  "$(status -X POST "$GATEWAY/v1/families" -H "Authorization: Bearer $JOIN_TOKEN")"

# ---- Leaving a household -------------------------------------------------------
#
# Joining one used to be permanent. An active membership blocks creating your own
# or asking another, and nothing could remove it, so erasing your account was the
# only way out - a right used as a workaround for a missing feature.
#
# JOIN_TOKEN heads a household of their own by this point, created by the check
# above. They leave it, which also exercises the head case: succession finds
# nobody, and the household is left inert rather than handed to a pending
# request.
check "the last member of a childless household may leave" 200 \
  "$(status -X DELETE "$GATEWAY/v1/families/mine/membership" \
     -H "Authorization: Bearer $JOIN_TOKEN")"

check "and leaving again is success rather than an error" 200 \
  "$(status -X DELETE "$GATEWAY/v1/families/mine/membership" \
     -H "Authorization: Bearer $JOIN_TOKEN")"

# Free again, which is what proves the membership is gone rather than hidden.
check "after which they can start another household" 201 \
  "$(status -X POST "$GATEWAY/v1/families" -H "Authorization: Bearer $JOIN_TOKEN")"

# The head of the smoke Samaaj's main household has children in it, added
# earlier, and is its only member. Leaving would leave those records with nobody
# able to manage them, and nothing on this platform can remove a child - so it is
# refused rather than allowed to orphan them.
check "but the last member of a household with children cannot" 409 \
  "$(status -X DELETE "$GATEWAY/v1/families/mine/membership" \
     -H "Authorization: Bearer $MEMBER_TOKEN")"


# The role travelled with the invitation, so this admin can do admin work
# without anyone granting them anything after activation.
check "and can immediately see their Samaaj's administrators" 200 \
  "$(status -H "Authorization: Bearer $SAMAAJ_ADMIN_TOKEN" "$GATEWAY/v1/identity/admins")"

check "but cannot decide which modules their Samaaj runs" 403 \
  "$(status -X PUT "$GATEWAY/v1/identity/tenants/$TENANT_ID/modules" \
     -H 'Content-Type: application/json' -H "Authorization: Bearer $SAMAAJ_ADMIN_TOKEN" \
     -d '{"enabledModules":["boli"]}')"

check "nor list every Samaaj on the platform" 403 \
  "$(status -H "Authorization: Bearer $SAMAAJ_ADMIN_TOKEN" "$GATEWAY/v1/identity/tenants")"

echo
echo "Notifications: reading your own, and announcing to the whole Samaaj"

# Every notification the member can see, before anything is marked. The welcome
# one raised by their registration event is in here.
FIRST_NOTIFICATION=$(curl -s -H "Authorization: Bearer $MEMBER_TOKEN" \
  "$GATEWAY/v1/notifications" | json_field id)

if [ -n "$FIRST_NOTIFICATION" ]; then
  echo "  ok    the member has a notification to read"
  pass=$((pass + 1))
else
  echo "  FAIL  the member has a notification to read"
  fail=$((fail + 1))
fi

check "marking it read" 200 \
  "$(status -X POST "$GATEWAY/v1/notifications/$FIRST_NOTIFICATION/read" \
     -H "Authorization: Bearer $MEMBER_TOKEN")"

# Pressing it twice is not an error - the member has done nothing wrong, and the
# response reports which happened. The unique index is what actually refuses the
# second row.
SECOND_READ=$(curl -s -X POST "$GATEWAY/v1/notifications/$FIRST_NOTIFICATION/read" \
  -H "Authorization: Bearer $MEMBER_TOKEN")

if printf '%s' "$SECOND_READ" | grep -q '"alreadyRead":true'; then
  echo "  ok    and marking it read again changes nothing and is not an error"
  pass=$((pass + 1))
else
  echo "  FAIL  a second read was treated as new (got '$SECOND_READ')"
  fail=$((fail + 1))
fi

check "a member may not announce to their Samaaj" 403 \
  "$(status -X POST "$GATEWAY/v1/notifications/broadcast" -H 'Content-Type: application/json' \
     -H "Authorization: Bearer $MEMBER_TOKEN" \
     -d '{"title":"Free money","body":"Send me your bank details."}')"

check "an announcement with no message is refused" 400 \
  "$(status -X POST "$GATEWAY/v1/notifications/broadcast" -H 'Content-Type: application/json' \
     -H "Authorization: Bearer $SAMAAJ_ADMIN_TOKEN" \
     -d '{"title":"Paryushan schedule","body":""}')"

BROADCAST=$(curl -s -X POST "$GATEWAY/v1/notifications/broadcast" \
  -H 'Content-Type: application/json' -H "Authorization: Bearer $SAMAAJ_ADMIN_TOKEN" \
  -d '{"title":"Paryushan schedule","body":"Timings for the week, and where to gather."}')

BROADCAST_ID=$(printf '%s' "$BROADCAST" | json_field id)

if [ -n "$BROADCAST_ID" ]; then
  echo "  ok    a Samaaj admin announces something to everybody"
  pass=$((pass + 1))
else
  echo "  FAIL  a Samaaj admin announces something (got '$BROADCAST')"
  fail=$((fail + 1))
fi

# The member never received this one personally; it is addressed to the Samaaj.
if curl -s -H "Authorization: Bearer $MEMBER_TOKEN" "$GATEWAY/v1/notifications" \
   | grep -q "$BROADCAST_ID"; then
  echo "  ok    and an ordinary member sees it in their list"
  pass=$((pass + 1))
else
  echo "  FAIL  the announcement did not reach a member's list"
  fail=$((fail + 1))
fi

# The point of a row per person: the member above has read their own welcome
# message, and that must not have marked this announcement read for them, nor
# for anybody else.
if curl -s -H "Authorization: Bearer $MEMBER_TOKEN" "$GATEWAY/v1/notifications" \
   | tr '{' '\n' | grep "$BROADCAST_ID" | grep -q '"readAt":null'; then
  echo "  ok    unread, because reading one message does not read another"
  pass=$((pass + 1))
else
  echo "  FAIL  the announcement came back already read"
  fail=$((fail + 1))
fi

check "marking everything read in one request" 200 \
  "$(status -X POST "$GATEWAY/v1/notifications/read-all" \
     -H "Authorization: Bearer $MEMBER_TOKEN")"

if curl -s -H "Authorization: Bearer $MEMBER_TOKEN" "$GATEWAY/v1/notifications" \
   | grep -q '"readAt":null'; then
  echo "  FAIL  something was still unread after mark-all"
  fail=$((fail + 1))
else
  echo "  ok    and nothing is left unread afterwards"
  pass=$((pass + 1))
fi

check "a member may not read the Samaaj's announcement history" 403 \
  "$(status -H "Authorization: Bearer $MEMBER_TOKEN" "$GATEWAY/v1/notifications/broadcasts")"

# The count the wireframe's "Delivered" column wanted to be: an in-app
# announcement is delivered the moment the row exists, so only a read count says
# anything.
#
# Matched with the closing brace, not as a bare prefix: `"readCount":1` also
# matches 10, 12 and 100, so on a Samaaj with a few members this check would
# have passed for a count it was not testing.
if curl -s -H "Authorization: Bearer $SAMAAJ_ADMIN_TOKEN" \
   "$GATEWAY/v1/notifications/broadcasts" | grep -q '"readCount":1}'; then
  echo "  ok    and the admin sees one member has opened it"
  pass=$((pass + 1))
else
  echo "  FAIL  the announcement's read count did not reach exactly 1"
  fail=$((fail + 1))
fi

# A broadcast is one person messaging everybody, so it has to be traceable to
# them. The row arrives over Kafka through this service's own outbox.
broadcast_audited=0
for attempt in $(seq 1 20); do
  if curl -s -H "Authorization: Bearer $ADMIN_TOKEN" -H "$ADMIN_TENANT_HEADER" \
     "$GATEWAY/v1/audit/logs?action=BroadcastSent" | grep -q "$BROADCAST_ID"; then
    broadcast_audited=1
    break
  fi
  sleep 2
done

if [ "$broadcast_audited" = "1" ]; then
  echo "  ok    and it is in the audit log, with the administrator who sent it"
  pass=$((pass + 1))
else
  echo "  FAIL  the announcement never reached the audit log"
  fail=$((fail + 1))
fi

check "granting a role" 200 \
  "$(status -X PUT "$GATEWAY/v1/identity/admins/$INVITED_ID/roles/BoliManager" \
     -H 'Content-Type: application/json' -H "Authorization: Bearer $ADMIN_TOKEN" \
     -H "$ADMIN_TENANT_HEADER" -d '{"granted":true}')"

check "SuperAdmin cannot be granted through this endpoint" 400 \
  "$(status -X PUT "$GATEWAY/v1/identity/admins/$INVITED_ID/roles/SuperAdmin" \
     -H 'Content-Type: application/json' -H "Authorization: Bearer $ADMIN_TOKEN" \
     -H "$ADMIN_TENANT_HEADER" -d '{"granted":true}')"

check "an admin cannot remove their own Samaaj Admin role" 409 \
  "$(status -X PUT "$GATEWAY/v1/identity/admins/$INVITED_ID/roles/SamaajAdmin" \
     -H 'Content-Type: application/json' -H "Authorization: Bearer $SAMAAJ_ADMIN_TOKEN" \
     -d '{"granted":false}')"

ADMINS=$(curl -s -H "Authorization: Bearer $ADMIN_TOKEN" -H "$ADMIN_TENANT_HEADER" \
  "$GATEWAY/v1/identity/admins")

if printf '%s' "$ADMINS" | grep -q "BoliManager"; then
  echo "  ok    the admin list shows the granted role"
  pass=$((pass + 1))
else
  echo "  FAIL  the admin list shows the granted role"
  fail=$((fail + 1))
fi

# Asserted on the roles, not on a name. This used to grep for "Smoke Member",
# and that member is reused between runs: the Pathshala section below grants
# them PathshalaTeacher, so on any re-run they appear in the admin list
# legitimately and the check failed for the right reason under the wrong name.
# The actual invariant is that somebody holding nothing but Member is not an
# administrator, and that does not depend on what a previous run did.
if printf '%s' "$ADMINS" | tr '{' '\n' | grep -q '"roles":\["Member"\]'; then
  echo "  FAIL  the admin list leaks members who hold no administrative role"
  fail=$((fail + 1))
else
  echo "  ok    the admin list omits members who hold no administrative role"
  pass=$((pass + 1))
fi

check "revoking a role" 200 \
  "$(status -X PUT "$GATEWAY/v1/identity/admins/$INVITED_ID/roles/BoliManager" \
     -H 'Content-Type: application/json' -H "Authorization: Bearer $ADMIN_TOKEN" \
     -H "$ADMIN_TENANT_HEADER" -d '{"granted":false}')"

check "the admin list is refused to a member" 403 \
  "$(status -H "Authorization: Bearer $MEMBER_TOKEN" "$GATEWAY/v1/identity/admins")"

echo
echo "DPDP section 12: erasure, across all three services"

# A throwaway account, because everything below this point still needs the
# member registered at the top to be able to sign in.
ERASE_STAMP="$(date +%s)"
ERASE_EMAIL="erasable-$ERASE_STAMP@example.com"

# The name is unique too, not just the address: the checks below search the
# directory for it, and a fixed name matches a throwaway member some earlier
# run left behind.
ERASE_NAME="Erasable Member $ERASE_STAMP"

check "a throwaway member registers" 201 \
  "$(status -X POST "$GATEWAY/v1/identity/register" -H 'Content-Type: application/json' \
     -d "{\"tenantSlug\":\"$SLUG\",\"fullName\":\"$ERASE_NAME\",\"mobileOrEmail\":\"$ERASE_EMAIL\",\"password\":\"$MEMBER_PASSWORD\",\"consentedPurposes\":[\"Membership\"],\"noticeVersion\":\"$NOTICE_VERSION\"}")"

ERASE_TOKEN=$(curl -s -X POST "$GATEWAY/v1/identity/login" -H 'Content-Type: application/json' \
  -d "{\"mobileOrEmail\":\"$ERASE_EMAIL\",\"password\":\"$MEMBER_PASSWORD\"}" | json_field accessToken)

ERASE_USER_ID=$(curl -s -H "Authorization: Bearer $ERASE_TOKEN" "$GATEWAY/v1/identity/me" \
  | json_field userId)

# There has to be something to erase before erasing proves anything.
erasable_profile=0
for attempt in $(seq 1 30); do
  if curl -s -H "Authorization: Bearer $ERASE_TOKEN" "$GATEWAY/v1/members/me" \
     | grep -q "$ERASE_NAME"; then
    erasable_profile=1
    break
  fi
  sleep 2
done
check "the throwaway profile arrives over Kafka" 1 "$erasable_profile"

# Both waits below are for something to *disappear*, so each needs proof it was
# there first - otherwise a check that runs before the event is consumed passes
# for the wrong reason.
listed_before=0
for attempt in $(seq 1 30); do
  if curl -s -H "Authorization: Bearer $MEMBER_TOKEN" "$GATEWAY/v1/members?search=Erasable+Member+$ERASE_STAMP" \
     | grep -q "$ERASE_NAME"; then
    listed_before=1
    break
  fi
  sleep 2
done
check "the throwaway member is in the directory first" 1 "$listed_before"

actor_recorded=0
for attempt in $(seq 1 30); do
  if curl -s -H "Authorization: Bearer $ADMIN_TOKEN" -H "$ADMIN_TENANT_HEADER" \
     "$GATEWAY/v1/audit/logs?limit=200" | grep -q "\"actorUserId\":\"$ERASE_USER_ID\""; then
    actor_recorded=1
    break
  fi
  sleep 2
done
check "their actions are on the audit record first" 1 "$actor_recorded"

# 403, not 401. The portals' interceptor reads a 401 as an expired access
# token: it renews the token and retries the original request, which here would
# resubmit the erasure because somebody mistyped.
check "a wrong password erases nothing" 403 \
  "$(status -X POST "$GATEWAY/v1/identity/me/erase" -H 'Content-Type: application/json' \
     -H "Authorization: Bearer $ERASE_TOKEN" -d '{"password":"not-the-password"}')"

check "still signed in after the refused attempt" 200 \
  "$(status -H "Authorization: Bearer $ERASE_TOKEN" "$GATEWAY/v1/identity/me")"

check "the member erases their own account" 200 \
  "$(status -X POST "$GATEWAY/v1/identity/me/erase" -H 'Content-Type: application/json' \
     -H "Authorization: Bearer $ERASE_TOKEN" -d "{\"password\":\"$MEMBER_PASSWORD\"}")"

check "an erased member cannot sign in" 401 \
  "$(status -X POST "$GATEWAY/v1/identity/login" -H 'Content-Type: application/json' \
     -d "{\"mobileOrEmail\":\"$ERASE_EMAIL\",\"password\":\"$MEMBER_PASSWORD\"}")"

# member-family-service consumes identity.user.erased.v1.
profile_erased=0
for attempt in $(seq 1 30); do
  if ! curl -s -H "Authorization: Bearer $MEMBER_TOKEN" "$GATEWAY/v1/members?search=Erasable+Member+$ERASE_STAMP" \
     | grep -q "$ERASE_NAME"; then
    profile_erased=1
    break
  fi
  sleep 2
done
check "the profile is erased in member-family-service" 1 "$profile_erased"

# audit-notification-service consumes it too, and de-identifies rather than
# deletes: the actions survive, the actor does not.
actor_gone=0
for attempt in $(seq 1 30); do
  if ! curl -s -H "Authorization: Bearer $ADMIN_TOKEN" -H "$ADMIN_TENANT_HEADER" \
     "$GATEWAY/v1/audit/logs?limit=200" | grep -q "\"actorUserId\":\"$ERASE_USER_ID\"" ; then
    actor_gone=1
    break
  fi
  sleep 2
done
check "the audit rows no longer name the actor" 1 "$actor_gone"

ERASURE_RECORDED=$(curl -s -H "Authorization: Bearer $ADMIN_TOKEN" -H "$ADMIN_TENANT_HEADER" \
  "$GATEWAY/v1/audit/logs?limit=200" | grep -c '"action":"Erased"' || true)

if [ "$ERASURE_RECORDED" -ge 1 ]; then
  echo "  ok    the erasure itself is on the record"
  pass=$((pass + 1))
else
  echo "  FAIL  the erasure itself is on the record (found none)"
  fail=$((fail + 1))
fi

echo

echo

echo

echo
echo "Timeline: posting, moderation, and the module gate"

# The first module-gated route on the platform, so this is also the first time
# ModuleGateMiddleware decides anything for real.
check "the community module is switched on for this Samaaj" 200 \
  "$(status -X PUT "$GATEWAY/v1/identity/tenants/$TENANT_ID/modules" \
     -H 'Content-Type: application/json' -H "Authorization: Bearer $ADMIN_TOKEN" \
     -d '{"enabledModules":["community","pathshala"]}')"

# The gateway caches what a Samaaj runs for 60 seconds, so a module change is
# not instant. Waiting is the honest way to test it.
sleep 62

check "a member reads the timeline" 200 \
  "$(status -H "Authorization: Bearer $MEMBER_TOKEN" "$GATEWAY/v1/timeline/posts")"

# A fresh title per run: the visibility checks below grep the feed for it,
# and a fixed title matches the post a previous run left approved.
POST_TITLE="Community blood donation drive $(date +%s)"

POST=$(curl -s -X POST "$GATEWAY/v1/timeline/posts" -H 'Content-Type: application/json' \
  -H "Authorization: Bearer $MEMBER_TOKEN" \
  -d "{\"title\":\"$POST_TITLE\",\"body\":\"Volunteers are welcome to participate.\",\"asAnnouncement\":false}")

POST_ID=$(printf '%s' "$POST" | json_field id)
POST_STATUS=$(printf '%s' "$POST" | json_field status)

if [ -n "$POST_ID" ] && [ "$POST_STATUS" = "PendingReview" ]; then
  echo "  ok    a member's post is created awaiting review"
  pass=$((pass + 1))
else
  echo "  FAIL  a member's post is created awaiting review (got '$POST_STATUS')"
  fail=$((fail + 1))
fi

check "a member cannot publish a Samaaj announcement" 403 \
  "$(status -X POST "$GATEWAY/v1/timeline/posts" -H 'Content-Type: application/json' \
     -H "Authorization: Bearer $MEMBER_TOKEN" \
     -d '{"title":"Announcement","body":"Straight to the timeline.","asAnnouncement":true}')"

check "nor moderate" 403 \
  "$(status -X POST "$GATEWAY/v1/timeline/posts/$POST_ID/moderate" -H 'Content-Type: application/json' \
     -H "Authorization: Bearer $MEMBER_TOKEN" -d '{"decision":"Approve"}')"

check "nor read the moderation queue" 403 \
  "$(status -H "Authorization: Bearer $MEMBER_TOKEN" \
     "$GATEWAY/v1/timeline/posts/moderation-queue")"

# The post is invisible to everyone but its author until it is approved.
if curl -s -H "Authorization: Bearer $ADMIN_TOKEN" -H "$ADMIN_TENANT_HEADER" \
   "$GATEWAY/v1/timeline/posts" | grep -q "$POST_TITLE"; then
  echo "  FAIL  an unapproved post is on the timeline"
  fail=$((fail + 1))
else
  echo "  ok    an unapproved post is not on the timeline"
  pass=$((pass + 1))
fi

if curl -s -H "Authorization: Bearer $ADMIN_TOKEN" -H "$ADMIN_TENANT_HEADER" \
   "$GATEWAY/v1/timeline/posts/moderation-queue" | grep -q "$POST_TITLE"; then
  echo "  ok    but it is in the moderation queue"
  pass=$((pass + 1))
else
  echo "  FAIL  the post did not reach the moderation queue"
  fail=$((fail + 1))
fi

# The admin panel renders these and derives nothing from the status, so an empty
# or missing list is a moderation screen with no buttons on it.
QUEUE_DECISIONS=$(curl -s -H "Authorization: Bearer $ADMIN_TOKEN" -H "$ADMIN_TENANT_HEADER" \
  "$GATEWAY/v1/timeline/posts/moderation-queue" \
  | tr '{' '\n' | grep -A 2 "$POST_ID" | grep -o '"availableDecisions":\[[^]]*\]' | head -1)

if [ -z "$QUEUE_DECISIONS" ]; then
  QUEUE_DECISIONS=$(curl -s -H "Authorization: Bearer $ADMIN_TOKEN" -H "$ADMIN_TENANT_HEADER" \
    "$GATEWAY/v1/timeline/posts/moderation-queue" \
    | grep -o '"availableDecisions":\[[^]]*\]' | head -1)
fi

if printf '%s' "$QUEUE_DECISIONS" | grep -q 'Approve' \
   && printf '%s' "$QUEUE_DECISIONS" | grep -q 'Reject'; then
  echo "  ok    and the queue says what a moderator may do with it"
  pass=$((pass + 1))
else
  echo "  FAIL  the queue offered no decisions (got '$QUEUE_DECISIONS')"
  fail=$((fail + 1))
fi

check "rejecting without saying why is refused" 400 \
  "$(status -X POST "$GATEWAY/v1/timeline/posts/$POST_ID/moderate" -H 'Content-Type: application/json' \
     -H "Authorization: Bearer $ADMIN_TOKEN" -H "$ADMIN_TENANT_HEADER" \
     -d '{"decision":"Reject"}')"

check "a moderator approves it" 200 \
  "$(status -X POST "$GATEWAY/v1/timeline/posts/$POST_ID/moderate" -H 'Content-Type: application/json' \
     -H "Authorization: Bearer $ADMIN_TOKEN" -H "$ADMIN_TENANT_HEADER" \
     -d '{"decision":"Approve"}')"

if curl -s -H "Authorization: Bearer $ADMIN_TOKEN" -H "$ADMIN_TENANT_HEADER" \
   "$GATEWAY/v1/timeline/posts" | grep -q "$POST_TITLE"; then
  echo "  ok    and it reaches the Samaaj's timeline"
  pass=$((pass + 1))
else
  echo "  FAIL  the approved post is not on the timeline"
  fail=$((fail + 1))
fi

check "commenting on an approved post" 201 \
  "$(status -X POST "$GATEWAY/v1/timeline/posts/$POST_ID/comments" -H 'Content-Type: application/json' \
     -H "Authorization: Bearer $MEMBER_TOKEN" -d '{"body":"Happy to help."}')"

check "reacting to it" 200 \
  "$(status -X PUT "$GATEWAY/v1/timeline/posts/$POST_ID/reaction" -H 'Content-Type: application/json' \
     -H "Authorization: Bearer $MEMBER_TOKEN" -d '{"reaction":"Appreciate"}')"

check "reporting it" 200 \
  "$(status -X POST "$GATEWAY/v1/timeline/posts/$POST_ID/report" \
     -H "Authorization: Bearer $MEMBER_TOKEN")"

# 404, not the handler's 403: a Super Admin with no Samaaj selected has no
# resolved tenant, and the module gate refuses a module route it cannot check
# before the request ever reaches the service. The handler check behind it is
# defence in depth for a caller who bypasses the gateway.
check "a post with no Samaaj selected never reaches the service" 404 \
  "$(status -X POST "$GATEWAY/v1/timeline/posts" -H 'Content-Type: application/json' \
     -H "Authorization: Bearer $ADMIN_TOKEN" \
     -d '{"title":"Nowhere","body":"No Samaaj selected.","asAnnouncement":false}')"

# Switching the module off must take the whole area away, not merely refuse it:
# a Samaaj that does not run a module should be indistinguishable from a
# platform that has no such feature (ARCHITECTURE.md section 6).
check "switching the community module off" 200 \
  "$(status -X PUT "$GATEWAY/v1/identity/tenants/$TENANT_ID/modules" \
     -H 'Content-Type: application/json' -H "Authorization: Bearer $ADMIN_TOKEN" \
     -d '{"enabledModules":["pathshala"]}')"

sleep 62

check "the timeline then answers 404, not 403" 404 \
  "$(status -H "Authorization: Bearer $MEMBER_TOKEN" "$GATEWAY/v1/timeline/posts")"

check "while an ungated route is unaffected" 200 \
  "$(status -H "Authorization: Bearer $MEMBER_TOKEN" "$GATEWAY/v1/identity/me")"

check "switching it back on" 200 \
  "$(status -X PUT "$GATEWAY/v1/identity/tenants/$TENANT_ID/modules" \
     -H 'Content-Type: application/json' -H "Authorization: Bearer $ADMIN_TOKEN" \
     -d '{"enabledModules":["community","pathshala"]}')"

# Wait the gateway's module cache out before the next section runs. Without
# this every module-gated check after here fails with a 404 that looks like a
# routing bug and is not one - the module really was off a moment ago.
sleep 62

echo
echo "Volunteer groups: applying, and the president's queue"

# Runs while the community module is on - the timeline section above switches it
# back on before finishing.
MEMBER_ID=$(curl -s -H "Authorization: Bearer $MEMBER_TOKEN" "$GATEWAY/v1/identity/me"   | json_field userId)
require_id member_id "$MEMBER_ID"

# The converted child from the conversion section: a second real member, so the
# applicant and the president are genuinely different people.
CHILD_TOKEN=$(curl -s -X POST "$GATEWAY/v1/identity/login" -H 'Content-Type: application/json'   -d "{\"mobileOrEmail\":\"$CHILD_EMAIL\",\"password\":\"$CHILD_PASSWORD\"}"   | json_field accessToken)

CHILD_USER_ID=$(curl -s -H "Authorization: Bearer $CHILD_TOKEN" "$GATEWAY/v1/identity/me"   | json_field userId)
require_id child_user_id "$CHILD_USER_ID"

# A fresh name per run: a group name is unique per Samaaj, so a fixed one
# turns every re-run into a 409 and every check after it into a cascade.
GROUP_NAME="Seva Group $(date +%s)"

GROUP=$(curl -s -X POST "$GATEWAY/v1/volunteer-groups/groups" -H 'Content-Type: application/json' \
  -H "Authorization: Bearer $ADMIN_TOKEN" -H "$ADMIN_TENANT_HEADER" \
  -d "{\"name\":\"$GROUP_NAME\",\"description\":\"Food drives and blood donation camps.\",\"focusArea\":\"Social Service\",\"presidentMemberId\":\"$MEMBER_ID\"}")

GROUP_ID=$(printf '%s' "$GROUP" | json_field id)

if [ -n "$GROUP_ID" ]; then
  echo "  ok    a Samaaj admin creates a group and names its president"
  pass=$((pass + 1))
else
  echo "  FAIL  a Samaaj admin creates a group ($GROUP)"
  fail=$((fail + 1))
fi

check "a second group cannot take the same name" 409 \
  "$(status -X POST "$GATEWAY/v1/volunteer-groups/groups" -H 'Content-Type: application/json' \
     -H "Authorization: Bearer $ADMIN_TOKEN" -H "$ADMIN_TENANT_HEADER" \
     -d "{\"name\":\"$GROUP_NAME\",\"description\":null,\"focusArea\":null,\"presidentMemberId\":\"$MEMBER_ID\"}")"

check "a member reads the group list" 200 \
  "$(status -H "Authorization: Bearer $MEMBER_TOKEN" "$GATEWAY/v1/volunteer-groups/groups")"

check "but cannot create one" 403 \
  "$(status -X POST "$GATEWAY/v1/volunteer-groups/groups" -H 'Content-Type: application/json' \
     -H "Authorization: Bearer $MEMBER_TOKEN" \
     -d "{\"name\":\"Unauthorised\",\"description\":null,\"focusArea\":null,\"presidentMemberId\":\"$MEMBER_ID\"}")"

check "another member applies to join" 200 \
  "$(status -X POST "$GATEWAY/v1/volunteer-groups/groups/$GROUP_ID/applications" \
     -H 'Content-Type: application/json' -H "Authorization: Bearer $CHILD_TOKEN" \
     -d '{"note":"Happy to help at weekends."}')"

check "the applicant cannot read the review queue" 404 \
  "$(status -H "Authorization: Bearer $CHILD_TOKEN" \
     "$GATEWAY/v1/volunteer-groups/groups/$GROUP_ID/applications")"

APPLICATIONS=$(curl -s -H "Authorization: Bearer $MEMBER_TOKEN" \
  "$GATEWAY/v1/volunteer-groups/groups/$GROUP_ID/applications")

APPLICATION_ID=$(printf '%s' "$APPLICATIONS" | json_field id)

if [ -n "$APPLICATION_ID" ]; then
  echo "  ok    the president sees it in their queue"
  pass=$((pass + 1))
else
  echo "  FAIL  the president sees it in their queue ($APPLICATIONS)"
  fail=$((fail + 1))
fi

# The note is the applicant's own words, for the president. It must not have
# travelled to the service that stores payloads verbatim.
if printf '%s' "$APPLICATIONS" | grep -q "weekends"; then
  echo "  ok    and can read what the applicant wrote"
  pass=$((pass + 1))
else
  echo "  FAIL  the application note did not reach the president"
  fail=$((fail + 1))
fi

# 404, not 403: everyone holds VolunteerGroups.Lead, so everyone passes the
# outer gate and is stopped by the presidency check - which answers "not
# found", because whose applications are waiting is the president's business.
check "a Samaaj admin who is not this president cannot decide it" 404 \
  "$(status -X POST "$GATEWAY/v1/volunteer-groups/groups/$GROUP_ID/applications/$APPLICATION_ID/decide" \
     -H 'Content-Type: application/json' -H "Authorization: Bearer $ADMIN_TOKEN" \
     -H "$ADMIN_TENANT_HEADER" -d '{"accept":true,"rolePosition":null}')"

check "the president accepts it" 200 \
  "$(status -X POST "$GATEWAY/v1/volunteer-groups/groups/$GROUP_ID/applications/$APPLICATION_ID/decide" \
     -H 'Content-Type: application/json' -H "Authorization: Bearer $MEMBER_TOKEN" \
     -d '{"accept":true,"rolePosition":"Coordinator"}')"

if curl -s -H "Authorization: Bearer $CHILD_TOKEN" \
   "$GATEWAY/v1/volunteer-groups/groups/$GROUP_ID" | grep -q '"iAmAMember":true'; then
  echo "  ok    and the applicant is now a member"
  pass=$((pass + 1))
else
  echo "  FAIL  the accepted applicant is not a member"
  fail=$((fail + 1))
fi

check "deciding the same application twice is refused" 404 \
  "$(status -X POST "$GATEWAY/v1/volunteer-groups/groups/$GROUP_ID/applications/$APPLICATION_ID/decide" \
     -H 'Content-Type: application/json' -H "Authorization: Bearer $MEMBER_TOKEN" \
     -d '{"accept":false,"rolePosition":null}')"

check "the president assigns a position" 200 \
  "$(status -X PUT "$GATEWAY/v1/volunteer-groups/groups/$GROUP_ID/members/$CHILD_USER_ID/position" \
     -H 'Content-Type: application/json' -H "Authorization: Bearer $MEMBER_TOKEN" \
     -d '{"rolePosition":"Secretary"}')"

check "deactivating the group" 200 \
  "$(status -X PATCH "$GATEWAY/v1/volunteer-groups/groups/$GROUP_ID/status" \
     -H 'Content-Type: application/json' -H "Authorization: Bearer $ADMIN_TOKEN" \
     -H "$ADMIN_TENANT_HEADER" -d '{"status":"Inactive"}')"


echo
echo "Events: publishing, capacity and the waitlist"

# Runs while the community module is on; the groups section above leaves it on
# and waits the gateway's cache out.
EVENT_START=$(date -u -d "+30 days" +%Y-%m-%dT%H:%M:%SZ 2>/dev/null \
  || date -u -v+30d +%Y-%m-%dT%H:%M:%SZ)

# A fresh title per run, like the post and group above: the visibility
# checks grep the list for it, and a fixed title matches whatever an
# earlier run left published.
EVENT_TITLE="Paryushan Lecture $(date +%s)"

EVENT=$(curl -s -X POST "$GATEWAY/v1/events" -H 'Content-Type: application/json' \
  -H "Authorization: Bearer $ADMIN_TOKEN" -H "$ADMIN_TENANT_HEADER" \
  -d "{\"title\":\"$EVENT_TITLE\",\"description\":\"An evening lecture.\",\"startAt\":\"$EVENT_START\",\"endAt\":null,\"venue\":\"Community Hall\",\"organizerType\":\"Samaaj\",\"organizerId\":null,\"registrationEnabled\":true,\"capacity\":1}")

EVENT_ID=$(printf '%s' "$EVENT" | json_field id)
require_id event_id "$EVENT_ID"
EVENT_STATUS=$(printf '%s' "$EVENT" | json_field status)

if [ "$EVENT_STATUS" = "Draft" ]; then
  echo "  ok    an event is created as a draft"
  pass=$((pass + 1))
else
  echo "  FAIL  an event is created as a draft (got '$EVENT_STATUS')"
  fail=$((fail + 1))
fi

check "a member cannot create one" 403 \
  "$(status -X POST "$GATEWAY/v1/events" -H 'Content-Type: application/json' \
     -H "Authorization: Bearer $MEMBER_TOKEN" \
     -d "{\"title\":\"Unauthorised\",\"description\":null,\"startAt\":\"$EVENT_START\",\"endAt\":null,\"venue\":null,\"organizerType\":\"Samaaj\",\"organizerId\":null,\"registrationEnabled\":true,\"capacity\":null}")"

# A draft is not an event anybody has been told about.
if curl -s -H "Authorization: Bearer $MEMBER_TOKEN" "$GATEWAY/v1/events" \
   | grep -q "$EVENT_TITLE"; then
  echo "  FAIL  an unpublished event is visible to members"
  fail=$((fail + 1))
else
  echo "  ok    an unpublished event is not visible to members"
  pass=$((pass + 1))
fi

check "a member cannot register for a draft" 404 \
  "$(status -X POST "$GATEWAY/v1/events/$EVENT_ID/registration" \
     -H "Authorization: Bearer $MEMBER_TOKEN")"

check "the organiser publishes it" 200 \
  "$(status -X POST "$GATEWAY/v1/events/$EVENT_ID/publish" \
     -H "Authorization: Bearer $ADMIN_TOKEN" -H "$ADMIN_TENANT_HEADER")"

if curl -s -H "Authorization: Bearer $MEMBER_TOKEN" "$GATEWAY/v1/events" \
   | grep -q "$EVENT_TITLE"; then
  echo "  ok    and it reaches the Samaaj"
  pass=$((pass + 1))
else
  echo "  FAIL  the published event did not reach the Samaaj"
  fail=$((fail + 1))
fi

RSVP=$(curl -s -X POST "$GATEWAY/v1/events/$EVENT_ID/registration" \
  -H "Authorization: Bearer $MEMBER_TOKEN")

if printf '%s' "$RSVP" | grep -q '"status":"Registered"'; then
  echo "  ok    the first member takes the only place"
  pass=$((pass + 1))
else
  echo "  FAIL  the first member takes the only place ($RSVP)"
  fail=$((fail + 1))
fi

# The wireframe's "Full - Waitlist" state, as a real outcome rather than a pill.
WAITLIST=$(curl -s -X POST "$GATEWAY/v1/events/$EVENT_ID/registration" \
  -H "Authorization: Bearer $CHILD_TOKEN")

if printf '%s' "$WAITLIST" | grep -q '"status":"Waitlisted"'; then
  echo "  ok    the second is waitlisted rather than refused"
  pass=$((pass + 1))
else
  echo "  FAIL  the second is waitlisted rather than refused ($WAITLIST)"
  fail=$((fail + 1))
fi

if curl -s -H "Authorization: Bearer $CHILD_TOKEN" "$GATEWAY/v1/events/$EVENT_ID" \
   | grep -q '"isFull":true'; then
  echo "  ok    and the event reports itself full"
  pass=$((pass + 1))
else
  echo "  FAIL  the event does not report itself full"
  fail=$((fail + 1))
fi

check "the attendee list is refused to a member" 403 \
  "$(status -H "Authorization: Bearer $MEMBER_TOKEN" "$GATEWAY/v1/events/$EVENT_ID/attendees")"

check "and served to the organiser" 200 \
  "$(status -H "Authorization: Bearer $ADMIN_TOKEN" -H "$ADMIN_TENANT_HEADER" \
     "$GATEWAY/v1/events/$EVENT_ID/attendees")"

# Giving up the place has to move the queue, or the waitlist is a list nobody
# comes off.
GAVE_UP=$(curl -s -X DELETE "$GATEWAY/v1/events/$EVENT_ID/registration" \
  -H "Authorization: Bearer $MEMBER_TOKEN")

if printf '%s' "$GAVE_UP" | grep -q '"promotedMemberId":"'; then
  echo "  ok    giving up the place promotes the member who was waiting"
  pass=$((pass + 1))
else
  echo "  FAIL  giving up the place promoted nobody ($GAVE_UP)"
  fail=$((fail + 1))
fi

if curl -s -H "Authorization: Bearer $CHILD_TOKEN" "$GATEWAY/v1/events/$EVENT_ID" \
   | grep -q '"myRegistrationStatus":"Registered"'; then
  echo "  ok    and they now hold a confirmed place"
  pass=$((pass + 1))
else
  echo "  FAIL  the promoted member does not hold a place"
  fail=$((fail + 1))
fi

check "cancelling an event without saying why is refused" 400 \
  "$(status -X POST "$GATEWAY/v1/events/$EVENT_ID/cancel" -H 'Content-Type: application/json' \
     -H "Authorization: Bearer $ADMIN_TOKEN" -H "$ADMIN_TENANT_HEADER" \
     -d '{"reason":null}')"

check "the organiser cancels it, with a reason" 200 \
  "$(status -X POST "$GATEWAY/v1/events/$EVENT_ID/cancel" -H 'Content-Type: application/json' \
     -H "Authorization: Bearer $ADMIN_TOKEN" -H "$ADMIN_TENANT_HEADER" \
     -d '{"reason":"The hall is unavailable."}')"

check "a cancelled event takes no more registrations" 409 \
  "$(status -X POST "$GATEWAY/v1/events/$EVENT_ID/registration" \
     -H "Authorization: Bearer $MEMBER_TOKEN")"

echo

# Volunteer groups sit behind the same community module as the timeline, so
# switching it off has to take both away.
check "switching the community module off" 200 \
  "$(status -X PUT "$GATEWAY/v1/identity/tenants/$TENANT_ID/modules" \
     -H 'Content-Type: application/json' -H "Authorization: Bearer $ADMIN_TOKEN" \
     -d '{"enabledModules":["pathshala"]}')"

sleep 62

check "the groups route then answers 404 as well" 404 \
  "$(status -H "Authorization: Bearer $MEMBER_TOKEN" "$GATEWAY/v1/volunteer-groups/groups")"

check "and so does the events route" 404 \
  "$(status -H "Authorization: Bearer $MEMBER_TOKEN" "$GATEWAY/v1/events")"

check "switching it back on" 200 \
  "$(status -X PUT "$GATEWAY/v1/identity/tenants/$TENANT_ID/modules" \
     -H 'Content-Type: application/json' -H "Authorization: Bearer $ADMIN_TOKEN" \
     -d '{"enabledModules":["community","pathshala"]}')"

sleep 62

echo

echo
echo "Social issues: the approval workflow, and a second module key"

# Social issues sit behind their own module, not `community`. Turning this one
# on must not disturb the timeline, and turning it off later must not take the
# timeline with it - which is the first time two module keys are exercised
# independently.
check "switching the social-issues module on alongside community" 200 \
  "$(status -X PUT "$GATEWAY/v1/identity/tenants/$TENANT_ID/modules" \
     -H 'Content-Type: application/json' -H "Authorization: Bearer $ADMIN_TOKEN" \
     -d '{"enabledModules":["community","pathshala","social-issues"]}')"

sleep 62

ISSUE_TITLE="Road safety near the community school $(date +%s)"

ISSUE=$(curl -s -X POST "$GATEWAY/v1/social-issues" -H 'Content-Type: application/json' \
  -H "Authorization: Bearer $MEMBER_TOKEN" \
  -d "{\"title\":\"$ISSUE_TITLE\",\"description\":\"Cars come through too fast at closing time.\",\"category\":\"Safety\",\"locality\":\"Hiran Magri\",\"submitNow\":true}")

ISSUE_ID=$(printf '%s' "$ISSUE" | json_field id)
require_id issue_id "$ISSUE_ID"
ISSUE_STATUS=$(printf '%s' "$ISSUE" | json_field status)

if [ "$ISSUE_STATUS" = "Submitted" ]; then
  echo "  ok    a member raises an issue and it awaits review"
  pass=$((pass + 1))
else
  echo "  FAIL  a member raises an issue (got '$ISSUE_STATUS')"
  fail=$((fail + 1))
fi

check "a category outside the list is refused" 400 \
  "$(status -X POST "$GATEWAY/v1/social-issues" -H 'Content-Type: application/json' \
     -H "Authorization: Bearer $MEMBER_TOKEN" \
     -d '{"title":"Anything","description":"Anything.","category":"Whatever I like","locality":null,"submitNow":true}')"

# Unpublished issues belong to their author and the reviewers.
if curl -s -H "Authorization: Bearer $CHILD_TOKEN" "$GATEWAY/v1/social-issues" \
   | grep -q "$ISSUE_TITLE"; then
  echo "  FAIL  an unpublished issue is visible to other members"
  fail=$((fail + 1))
else
  echo "  ok    an unpublished issue is not visible to other members"
  pass=$((pass + 1))
fi

if curl -s -H "Authorization: Bearer $MEMBER_TOKEN" "$GATEWAY/v1/social-issues" \
   | grep -q "$ISSUE_TITLE"; then
  echo "  ok    but its author sees it in their own list"
  pass=$((pass + 1))
else
  echo "  FAIL  the author cannot see their own submission"
  fail=$((fail + 1))
fi

check "the approval queue is refused to a member" 403 \
  "$(status -H "Authorization: Bearer $MEMBER_TOKEN" "$GATEWAY/v1/social-issues/approval-queue")"

if curl -s -H "Authorization: Bearer $ADMIN_TOKEN" -H "$ADMIN_TENANT_HEADER" \
   "$GATEWAY/v1/social-issues/approval-queue" | grep -q "$ISSUE_TITLE"; then
  echo "  ok    and served to a reviewer, with the issue in it"
  pass=$((pass + 1))
else
  echo "  FAIL  the issue did not reach the approval queue"
  fail=$((fail + 1))
fi

check "a member cannot decide about their own issue" 403 \
  "$(status -X POST "$GATEWAY/v1/social-issues/$ISSUE_ID/status" -H 'Content-Type: application/json' \
     -H "Authorization: Bearer $MEMBER_TOKEN" -d '{"status":"Approved","reason":null}')"

# The one promise this service makes.
check "publishing without approval is refused" 409 \
  "$(status -X POST "$GATEWAY/v1/social-issues/$ISSUE_ID/status" -H 'Content-Type: application/json' \
     -H "Authorization: Bearer $ADMIN_TOKEN" -H "$ADMIN_TENANT_HEADER" \
     -d '{"status":"Published","reason":null}')"

check "rejecting without saying why is refused" 400 \
  "$(status -X POST "$GATEWAY/v1/social-issues/$ISSUE_ID/status" -H 'Content-Type: application/json' \
     -H "Authorization: Bearer $ADMIN_TOKEN" -H "$ADMIN_TENANT_HEADER" \
     -d '{"status":"Rejected","reason":null}')"

check "a reviewer sends it back for changes" 200 \
  "$(status -X POST "$GATEWAY/v1/social-issues/$ISSUE_ID/status" -H 'Content-Type: application/json' \
     -H "Authorization: Bearer $ADMIN_TOKEN" -H "$ADMIN_TENANT_HEADER" \
     -d '{"status":"ChangesRequested","reason":"Please add the road name."}')"

check "the author revises it" 200 \
  "$(status -X PUT "$GATEWAY/v1/social-issues/$ISSUE_ID" -H 'Content-Type: application/json' \
     -H "Authorization: Bearer $MEMBER_TOKEN" \
     -d "{\"title\":\"$ISSUE_TITLE\",\"description\":\"Cars come through too fast on the main road at closing time.\",\"category\":\"Safety\",\"locality\":\"Hiran Magri\"}")"

check "and resubmits it" 200 \
  "$(status -X POST "$GATEWAY/v1/social-issues/$ISSUE_ID/status" -H 'Content-Type: application/json' \
     -H "Authorization: Bearer $MEMBER_TOKEN" -d '{"status":"Submitted","reason":null}')"

check "the reviewer approves it" 200 \
  "$(status -X POST "$GATEWAY/v1/social-issues/$ISSUE_ID/status" -H 'Content-Type: application/json' \
     -H "Authorization: Bearer $ADMIN_TOKEN" -H "$ADMIN_TENANT_HEADER" \
     -d '{"status":"Approved","reason":null}')"

check "and publishes it" 200 \
  "$(status -X POST "$GATEWAY/v1/social-issues/$ISSUE_ID/status" -H 'Content-Type: application/json' \
     -H "Authorization: Bearer $ADMIN_TOKEN" -H "$ADMIN_TENANT_HEADER" \
     -d '{"status":"Published","reason":null}')"

if curl -s -H "Authorization: Bearer $CHILD_TOKEN" "$GATEWAY/v1/social-issues" \
   | grep -q "$ISSUE_TITLE"; then
  echo "  ok    the published issue reaches the whole Samaaj"
  pass=$((pass + 1))
else
  echo "  FAIL  the published issue did not reach the Samaaj"
  fail=$((fail + 1))
fi

# The history is what answers "why was mine sent back?".
if curl -s -H "Authorization: Bearer $MEMBER_TOKEN" "$GATEWAY/v1/social-issues/$ISSUE_ID" \
   | grep -q "Please add the road name."; then
  echo "  ok    and its author can still read why it was sent back"
  pass=$((pass + 1))
else
  echo "  FAIL  the issue history lost the reviewer's reason"
  fail=$((fail + 1))
fi

check "a published issue can no longer be edited" 409 \
  "$(status -X PUT "$GATEWAY/v1/social-issues/$ISSUE_ID" -H 'Content-Type: application/json' \
     -H "Authorization: Bearer $MEMBER_TOKEN" \
     -d '{"title":"Something else entirely","description":"Rewritten after approval.","category":"Community","locality":null}')"

# Two module keys, gated independently.
check "switching the social-issues module off alone" 200 \
  "$(status -X PUT "$GATEWAY/v1/identity/tenants/$TENANT_ID/modules" \
     -H 'Content-Type: application/json' -H "Authorization: Bearer $ADMIN_TOKEN" \
     -d '{"enabledModules":["community","pathshala"]}')"

sleep 62

check "the social-issues route answers 404" 404 \
  "$(status -H "Authorization: Bearer $MEMBER_TOKEN" "$GATEWAY/v1/social-issues")"

check "while the timeline, on a different module, is untouched" 200 \
  "$(status -H "Authorization: Bearer $MEMBER_TOKEN" "$GATEWAY/v1/timeline/posts")"

echo
echo "Celebrities of Samaaj: nominations, one vote each, a frozen result"

check "switching the celebrity-voting module on" 200 \
  "$(status -X PUT "$GATEWAY/v1/identity/tenants/$TENANT_ID/modules" \
     -H 'Content-Type: application/json' -H "Authorization: Bearer $ADMIN_TOKEN" \
     -d '{"enabledModules":["community","pathshala","celebrity-voting"]}')"

sleep 62

# A campaign runs over time, and nominations and voting are deliberately never
# open at once - members who vote early must see the same ballot as members who
# vote late. So this section has a real window to wait out. Forty-five seconds
# is the smallest one that leaves room for the calls in between.
CAMPAIGN_TITLE="Celebrities of Samaaj $(date +%s)"
NOMINATIONS_CLOSE=$(date -u -d '+45 seconds' +%Y-%m-%dT%H:%M:%SZ)
VOTING_CLOSES=$(date -u -d '+7 days' +%Y-%m-%dT%H:%M:%SZ)
NOMINATIONS_OPENED=$(date -u -d '-1 minute' +%Y-%m-%dT%H:%M:%SZ)

# Nominated so that a member cannot vote for themselves later.
OTHER_MEMBER="dddddddd-0000-4000-8000-00000000d001"

CAMPAIGN=$(curl -s -X POST "$GATEWAY/v1/celebrity-voting/campaigns" \
  -H 'Content-Type: application/json' \
  -H "Authorization: Bearer $ADMIN_TOKEN" -H "$ADMIN_TENANT_HEADER" \
  -d "{\"title\":\"$CAMPAIGN_TITLE\",\"description\":null,\"nominationStartAt\":\"$NOMINATIONS_OPENED\",\"nominationEndAt\":\"$NOMINATIONS_CLOSE\",\"votingStartAt\":\"$NOMINATIONS_CLOSE\",\"votingEndAt\":\"$VOTING_CLOSES\",\"topN\":3,\"resultsVisibility\":\"Live\"}")

CAMPAIGN_ID=$(printf '%s' "$CAMPAIGN" | json_field id)

if [ -n "$CAMPAIGN_ID" ]; then
  echo "  ok    an administrator sets a campaign up"
  pass=$((pass + 1))
else
  echo "  FAIL  an administrator sets a campaign up"
  fail=$((fail + 1))
fi

check "a voting window that opens before nominations close is refused" 400 \
  "$(status -X POST "$GATEWAY/v1/celebrity-voting/campaigns" -H 'Content-Type: application/json' \
     -H "Authorization: Bearer $ADMIN_TOKEN" -H "$ADMIN_TENANT_HEADER" \
     -d "{\"title\":\"Overlapping\",\"description\":null,\"nominationStartAt\":\"$NOMINATIONS_OPENED\",\"nominationEndAt\":\"$VOTING_CLOSES\",\"votingStartAt\":\"$NOMINATIONS_CLOSE\",\"votingEndAt\":\"$VOTING_CLOSES\",\"topN\":3,\"resultsVisibility\":\"Live\"}")"

check "a member cannot set one up" 403 \
  "$(status -X POST "$GATEWAY/v1/celebrity-voting/campaigns" -H 'Content-Type: application/json' \
     -H "Authorization: Bearer $MEMBER_TOKEN" \
     -d "{\"title\":\"Mine\",\"description\":null,\"nominationStartAt\":\"$NOMINATIONS_OPENED\",\"nominationEndAt\":\"$NOMINATIONS_CLOSE\",\"votingStartAt\":\"$NOMINATIONS_CLOSE\",\"votingEndAt\":\"$VOTING_CLOSES\",\"topN\":3,\"resultsVisibility\":\"Live\"}")"

check "voting cannot open before the ballot has anyone on it" 409 \
  "$(status -X POST "$GATEWAY/v1/celebrity-voting/campaigns/$CAMPAIGN_ID/status" \
     -H 'Content-Type: application/json' \
     -H "Authorization: Bearer $ADMIN_TOKEN" -H "$ADMIN_TENANT_HEADER" \
     -d '{"status":"VotingOpen"}')"

check "opening nominations is accepted" 200 \
  "$(status -X POST "$GATEWAY/v1/celebrity-voting/campaigns/$CAMPAIGN_ID/status" \
     -H 'Content-Type: application/json' \
     -H "Authorization: Bearer $ADMIN_TOKEN" -H "$ADMIN_TENANT_HEADER" \
     -d '{"status":"NominationsOpen"}')"

NOMINATION=$(curl -s -X POST "$GATEWAY/v1/celebrity-voting/campaigns/$CAMPAIGN_ID/candidates" \
  -H 'Content-Type: application/json' -H "Authorization: Bearer $MEMBER_TOKEN" \
  -d "{\"memberId\":\"$OTHER_MEMBER\",\"category\":\"Community service\"}")

CANDIDATE_ID=$(printf '%s' "$NOMINATION" | json_field candidateId)

if [ -n "$CANDIDATE_ID" ]; then
  echo "  ok    a member puts somebody forward"
  pass=$((pass + 1))
else
  echo "  FAIL  a member puts somebody forward"
  fail=$((fail + 1))
fi

# Nominating themselves, so the self-vote refusal below has something to refuse.
SELF_NOMINATION=$(curl -s -X POST "$GATEWAY/v1/celebrity-voting/campaigns/$CAMPAIGN_ID/candidates" \
  -H 'Content-Type: application/json' -H "Authorization: Bearer $CHILD_TOKEN" \
  -d "{\"memberId\":\"$MEMBER_ID\",\"category\":\"Community service\"}")

SELF_CANDIDATE_ID=$(printf '%s' "$SELF_NOMINATION" | json_field candidateId)
require_id self_candidate_id "$SELF_CANDIDATE_ID"

# A second nomination of the same person is a no-op, not an error: two entries
# for one person split their vote, and the second nominator did nothing wrong.
REPEAT=$(curl -s -X POST "$GATEWAY/v1/celebrity-voting/campaigns/$CAMPAIGN_ID/candidates" \
  -H 'Content-Type: application/json' -H "Authorization: Bearer $CHILD_TOKEN" \
  -d "{\"memberId\":\"$OTHER_MEMBER\",\"category\":\"Community service\"}")

if printf '%s' "$REPEAT" | grep -q "$CANDIDATE_ID"; then
  echo "  ok    nominating the same person twice returns the one candidacy"
  pass=$((pass + 1))
else
  echo "  FAIL  a second nomination created a second candidacy"
  fail=$((fail + 1))
fi

check "a member cannot approve a nomination" 403 \
  "$(status -X POST "$GATEWAY/v1/celebrity-voting/campaigns/$CAMPAIGN_ID/candidates/$CANDIDATE_ID/decide" \
     -H 'Content-Type: application/json' -H "Authorization: Bearer $MEMBER_TOKEN" \
     -d '{"approve":true}')"

check "a reviewer puts them on the ballot" 200 \
  "$(status -X POST "$GATEWAY/v1/celebrity-voting/campaigns/$CAMPAIGN_ID/candidates/$CANDIDATE_ID/decide" \
     -H 'Content-Type: application/json' \
     -H "Authorization: Bearer $ADMIN_TOKEN" -H "$ADMIN_TENANT_HEADER" \
     -d '{"approve":true}')"

check "and the second one too" 200 \
  "$(status -X POST "$GATEWAY/v1/celebrity-voting/campaigns/$CAMPAIGN_ID/candidates/$SELF_CANDIDATE_ID/decide" \
     -H 'Content-Type: application/json' \
     -H "Authorization: Bearer $ADMIN_TOKEN" -H "$ADMIN_TENANT_HEADER" \
     -d '{"approve":true}')"

check "voting is not open while nominations still are" 409 \
  "$(status -X POST "$GATEWAY/v1/celebrity-voting/campaigns/$CAMPAIGN_ID/votes" \
     -H 'Content-Type: application/json' -H "Authorization: Bearer $MEMBER_TOKEN" \
     -d "{\"candidateId\":\"$CANDIDATE_ID\"}")"

echo "  ..    waiting for nominations to close"
while [ "$(date -u +%s)" -lt "$(date -u -d "$NOMINATIONS_CLOSE" +%s)" ]; do
  sleep 2
done

check "opening voting is accepted" 200 \
  "$(status -X POST "$GATEWAY/v1/celebrity-voting/campaigns/$CAMPAIGN_ID/status" \
     -H 'Content-Type: application/json' \
     -H "Authorization: Bearer $ADMIN_TOKEN" -H "$ADMIN_TENANT_HEADER" \
     -d '{"status":"VotingOpen"}')"

FIRST_VOTE=$(curl -s -X POST "$GATEWAY/v1/celebrity-voting/campaigns/$CAMPAIGN_ID/votes" \
  -H 'Content-Type: application/json' -H "Authorization: Bearer $MEMBER_TOKEN" \
  -d "{\"candidateId\":\"$CANDIDATE_ID\"}")

if printf '%s' "$FIRST_VOTE" | grep -q '"accepted":true'; then
  echo "  ok    a member casts their vote"
  pass=$((pass + 1))
else
  echo "  FAIL  a member casts their vote (got '$FIRST_VOTE')"
  fail=$((fail + 1))
fi

# The second press is success with accepted=false: they have done nothing
# wrong, and the response tells them what they hold. The unique index on
# (CampaignId, VoterMemberId) is what actually refuses it.
# The same candidate again, deliberately. Pressing it a second time with a
# *different* candidate would hit whichever rule that candidate happens to
# break first - and it did: this used SELF_CANDIDATE_ID, so the second press was
# refused for being a self-vote and this check never once exercised the
# already-voted path it is named after.
SECOND_VOTE=$(curl -s -X POST "$GATEWAY/v1/celebrity-voting/campaigns/$CAMPAIGN_ID/votes" \
  -H 'Content-Type: application/json' -H "Authorization: Bearer $MEMBER_TOKEN" \
  -d "{\"candidateId\":\"$CANDIDATE_ID\"}")

if printf '%s' "$SECOND_VOTE" | grep -q '"accepted":false'; then
  echo "  ok    voting a second time changes nothing and is not an error"
  pass=$((pass + 1))
else
  echo "  FAIL  a second vote was accepted (got '$SECOND_VOTE')"
  fail=$((fail + 1))
fi

# SELF_CANDIDATE_ID is MEMBER nominated as a candidate, so it is MEMBER's own
# token that makes this a self-vote. With CHILD_TOKEN - which this used - it is
# simply somebody voting for a candidate who is not them, and the 200 that came
# back was correct. The check was wrong, and it was also quietly casting a
# second vote in a campaign the next checks then tally.
check "and nobody may vote for themselves" 409 \
  "$(status -X POST "$GATEWAY/v1/celebrity-voting/campaigns/$CAMPAIGN_ID/votes" \
     -H 'Content-Type: application/json' -H "Authorization: Bearer $MEMBER_TOKEN" \
     -d "{\"candidateId\":\"$SELF_CANDIDATE_ID\"}")"

check "a candidate who is not on this ballot is not found" 404 \
  "$(status -X POST "$GATEWAY/v1/celebrity-voting/campaigns/$CAMPAIGN_ID/votes" \
     -H 'Content-Type: application/json' -H "Authorization: Bearer $CHILD_TOKEN" \
     -d '{"candidateId":"11111111-2222-4333-8444-555555555555"}')"

check "a candidate cannot be removed once voting has opened" 409 \
  "$(status -X POST "$GATEWAY/v1/celebrity-voting/campaigns/$CAMPAIGN_ID/candidates/$CANDIDATE_ID/decide" \
     -H 'Content-Type: application/json' \
     -H "Authorization: Bearer $ADMIN_TOKEN" -H "$ADMIN_TENANT_HEADER" \
     -d '{"approve":false}')"

if curl -s -H "Authorization: Bearer $MEMBER_TOKEN" \
   "$GATEWAY/v1/celebrity-voting/campaigns/$CAMPAIGN_ID" | grep -q '"votes":1'; then
  echo "  ok    the tally counts exactly one vote"
  pass=$((pass + 1))
else
  echo "  FAIL  the tally does not show one vote"
  fail=$((fail + 1))
fi

check "results cannot be published while voting is open" 409 \
  "$(status -X POST "$GATEWAY/v1/celebrity-voting/campaigns/$CAMPAIGN_ID/results" \
     -H "Authorization: Bearer $ADMIN_TOKEN" -H "$ADMIN_TENANT_HEADER")"

check "closing the campaign is accepted" 200 \
  "$(status -X POST "$GATEWAY/v1/celebrity-voting/campaigns/$CAMPAIGN_ID/status" \
     -H 'Content-Type: application/json' \
     -H "Authorization: Bearer $ADMIN_TOKEN" -H "$ADMIN_TENANT_HEADER" \
     -d '{"status":"Closed"}')"

check "and a closed campaign takes no more votes" 409 \
  "$(status -X POST "$GATEWAY/v1/celebrity-voting/campaigns/$CAMPAIGN_ID/votes" \
     -H 'Content-Type: application/json' -H "Authorization: Bearer $CHILD_TOKEN" \
     -d "{\"candidateId\":\"$CANDIDATE_ID\"}")"

check "an unpublished result is not found" 404 \
  "$(status -H "Authorization: Bearer $MEMBER_TOKEN" \
     "$GATEWAY/v1/celebrity-voting/campaigns/$CAMPAIGN_ID/results")"

FIRST_PUBLISH=$(curl -s -X POST "$GATEWAY/v1/celebrity-voting/campaigns/$CAMPAIGN_ID/results" \
  -H "Authorization: Bearer $ADMIN_TOKEN" -H "$ADMIN_TENANT_HEADER")

if printf '%s' "$FIRST_PUBLISH" | grep -q '"publishedAt"'; then
  echo "  ok    publishing the result is accepted"
  pass=$((pass + 1))
else
  echo "  FAIL  publishing the result is accepted (got '$FIRST_PUBLISH')"
  fail=$((fail + 1))
fi

# What matters is that the announced order cannot move, not that the second
# press errors. PublishResultsCommandHandler returns the stored result rather
# than recomputing one - the same shape as pressing Vote twice, where doing the
# thing again is not a mistake to report. This check asked for a 409 and so
# asserted the opposite of what the service deliberately does; it now asserts
# the property the comment was actually about.
SECOND_PUBLISH=$(curl -s -X POST "$GATEWAY/v1/celebrity-voting/campaigns/$CAMPAIGN_ID/results" \
  -H "Authorization: Bearer $ADMIN_TOKEN" -H "$ADMIN_TENANT_HEADER")

# The ranking and who published it, not the whole body. The two responses
# legitimately differ in `publishedAt`: the first is the in-memory timestamp,
# which .NET keeps to 100ns, and the second is read back from Postgres, which
# stores microseconds - so the last digit disappears in the round trip. That is
# cosmetic, and comparing the bodies verbatim failed on it while the result
# itself had not moved an inch.
ranking_of() { printf '%s' "$1" | sed 's/.*"ranking":\[//; s/\],"publishedBy".*//'; }

if [ -n "$FIRST_PUBLISH" ] \
   && [ "$(ranking_of "$SECOND_PUBLISH")" = "$(ranking_of "$FIRST_PUBLISH")" ] \
   && [ "$(printf '%s' "$SECOND_PUBLISH" | json_field publishedBy)" \
      = "$(printf '%s' "$FIRST_PUBLISH" | json_field publishedBy)" ]; then
  echo "  ok    publishing twice returns the frozen result, unchanged"
  pass=$((pass + 1))
else
  echo "  FAIL  a second publish changed the result"
  echo "        first:  $FIRST_PUBLISH"
  echo "        second: $SECOND_PUBLISH"
  fail=$((fail + 1))
fi

if curl -s -H "Authorization: Bearer $MEMBER_TOKEN" \
   "$GATEWAY/v1/celebrity-voting/campaigns/$CAMPAIGN_ID/results" | grep -q "$CANDIDATE_ID"; then
  echo "  ok    and the Samaaj can read the published ranking"
  pass=$((pass + 1))
else
  echo "  FAIL  the published ranking is not readable"
  fail=$((fail + 1))
fi

check "switching the celebrity-voting module off again" 200 \
  "$(status -X PUT "$GATEWAY/v1/identity/tenants/$TENANT_ID/modules" \
     -H 'Content-Type: application/json' -H "Authorization: Bearer $ADMIN_TOKEN" \
     -d '{"enabledModules":["community","pathshala"]}')"

sleep 62

check "the celebrity-voting route answers 404" 404 \
  "$(status -H "Authorization: Bearer $MEMBER_TOKEN" "$GATEWAY/v1/celebrity-voting/campaigns")"

check "while the timeline, on a different module, is untouched" 200 \
  "$(status -H "Authorization: Bearer $MEMBER_TOKEN" "$GATEWAY/v1/timeline/posts")"

echo
echo "Sessions: rotation, reuse detection and sign-out"

SESSION_LOGIN=$(curl -s -X POST "$GATEWAY/v1/identity/login" -H 'Content-Type: application/json' \
  -d "{\"mobileOrEmail\":\"$MEMBER\",\"password\":\"$MEMBER_PASSWORD\"}")

REFRESH_1=$(printf '%s' "$SESSION_LOGIN" | json_field refreshToken)

if [ -n "$REFRESH_1" ]; then
  echo "  ok    signing in returns a refresh token"
  pass=$((pass + 1))
else
  echo "  FAIL  signing in returns a refresh token"
  fail=$((fail + 1))
fi

REFRESHED=$(curl -s -X POST "$GATEWAY/v1/identity/token/refresh" -H 'Content-Type: application/json' \
  -d "{\"refreshToken\":\"$REFRESH_1\"}")

REFRESH_2=$(printf '%s' "$REFRESHED" | json_field refreshToken)
ACCESS_2=$(printf '%s' "$REFRESHED" | json_field accessToken)

if [ -n "$REFRESH_2" ] && [ "$REFRESH_2" != "$REFRESH_1" ]; then
  echo "  ok    refreshing rotates the token"
  pass=$((pass + 1))
else
  echo "  FAIL  refreshing rotates the token"
  fail=$((fail + 1))
fi

check "the new access token works" 200 \
  "$(status -H "Authorization: Bearer $ACCESS_2" "$GATEWAY/v1/identity/me")"

check "spending a refresh token twice is refused" 401 \
  "$(status -X POST "$GATEWAY/v1/identity/token/refresh" -H 'Content-Type: application/json' \
     -d "{\"refreshToken\":\"$REFRESH_1\"}")"

# The theft response: the live token in that chain dies with the replayed one.
check "and kills the live token in the same session" 401 \
  "$(status -X POST "$GATEWAY/v1/identity/token/refresh" -H 'Content-Type: application/json' \
     -d "{\"refreshToken\":\"$REFRESH_2\"}")"

SESSION_LOGIN=$(curl -s -X POST "$GATEWAY/v1/identity/login" -H 'Content-Type: application/json' \
  -d "{\"mobileOrEmail\":\"$MEMBER\",\"password\":\"$MEMBER_PASSWORD\"}")
REFRESH_3=$(printf '%s' "$SESSION_LOGIN" | json_field refreshToken)

check "signing out is accepted" 200 \
  "$(status -X POST "$GATEWAY/v1/identity/logout" -H 'Content-Type: application/json' \
     -d "{\"refreshToken\":\"$REFRESH_3\"}")"

check "and the session cannot be continued afterwards" 401 \
  "$(status -X POST "$GATEWAY/v1/identity/token/refresh" -H 'Content-Type: application/json' \
     -d "{\"refreshToken\":\"$REFRESH_3\"}")"

check "signing out with an unknown token is not an error" 200 \
  "$(status -X POST "$GATEWAY/v1/identity/logout" -H 'Content-Type: application/json' \
     -d '{"refreshToken":"not-a-real-token"}')"

check "a refresh token nobody issued is refused" 401 \
  "$(status -X POST "$GATEWAY/v1/identity/token/refresh" -H 'Content-Type: application/json' \
     -d '{"refreshToken":"not-a-real-token"}')"

echo
echo "Jain Pathshala: enrolment in two steps, a register, an exam"

check "switching the pathshala module on" 200 \
  "$(status -X PUT "$GATEWAY/v1/identity/tenants/$TENANT_ID/modules" \
     -H 'Content-Type: application/json' -H "Authorization: Bearer $ADMIN_TOKEN" \
     -d '{"enabledModules":["community","pathshala"]}')"

sleep 62

# Only a Super Admin creates the master record (DATA-MODEL.md section 9); the
# Samaaj runs it afterwards. ADMIN_TOKEN is the platform account, so it can do
# both - the refusals below use the Samaaj Admin token instead.
PATHSHALA=$(curl -s -X POST "$GATEWAY/v1/pathshala/pathshalas" \
  -H 'Content-Type: application/json' \
  -H "Authorization: Bearer $ADMIN_TOKEN" -H "$ADMIN_TENANT_HEADER" \
  -d '{"name":"Shri Mahavir Jain Pathshala","address":"Hiran Magri","contactPerson":"Smt. Kavita Jain"}')

PATHSHALA_ID=$(printf '%s' "$PATHSHALA" | json_field id)

if [ -n "$PATHSHALA_ID" ]; then
  echo "  ok    a Super Admin creates the Pathshala"
  pass=$((pass + 1))
else
  echo "  FAIL  a Super Admin creates the Pathshala"
  fail=$((fail + 1))
fi

check "a Samaaj Admin cannot create one" 403 \
  "$(status -X POST "$GATEWAY/v1/pathshala/pathshalas" -H 'Content-Type: application/json' \
     -H "Authorization: Bearer $SAMAAJ_ADMIN_TOKEN" \
     -d '{"name":"Ours","address":null,"contactPerson":null}')"

check "a member cannot either" 403 \
  "$(status -X POST "$GATEWAY/v1/pathshala/pathshalas" -H 'Content-Type: application/json' \
     -H "Authorization: Bearer $MEMBER_TOKEN" \
     -d '{"name":"Mine","address":null,"contactPerson":null}')"

# A Pathshala with no current session has nowhere to put a child.
check "it takes no enrolments before a session is open" 409 \
  "$(status -X POST "$GATEWAY/v1/pathshala/pathshalas/$PATHSHALA_ID/enrollments" \
     -H 'Content-Type: application/json' -H "Authorization: Bearer $MEMBER_TOKEN" \
     -d "{\"childProfileId\":\"$CHILD_ID\"}")"

# Running it is the Samaaj's job, and this is the half that would have been
# unreachable if Pathshala.Manage had been withheld to reserve creation.
SESSION=$(curl -s -X POST "$GATEWAY/v1/pathshala/pathshalas/$PATHSHALA_ID/sessions" \
  -H 'Content-Type: application/json' -H "Authorization: Bearer $SAMAAJ_ADMIN_TOKEN" \
  -d '{"label":"2026-27","startDate":"2026-03-01","endDate":"2027-02-28"}')

if printf '%s' "$SESSION" | grep -q '"isCurrent":true'; then
  echo "  ok    a Samaaj Admin opens the academic session"
  pass=$((pass + 1))
else
  echo "  FAIL  a Samaaj Admin opens the academic session"
  fail=$((fail + 1))
fi

# Opening a session answers with the whole Pathshala, so the *first* "id" in the
# response is the Pathshala's and not the session's. `json_field id` takes the
# first match, so this used to hand the Pathshala's own id back as SESSION_ID -
# and every Pathshala check after it failed with Session.NotFound while the
# check immediately above passed, because the session really had been opened.
# Seventeen red lines, one wrong field, and nothing pointing at it.
SESSION_ID=$(printf '%s' "$SESSION" \
  | sed 's/.*"sessions":\[//; s/\],"classes".*//' \
  | tr '}' '\n' \
  | grep '"isCurrent":true' \
  | json_field id)

# Named separately rather than folded into the next check, because the failure
# it guards against is not "no id" - it is "a plausible id belonging to
# something else", which every downstream check reports as someone else's bug.
if [ -n "$SESSION_ID" ] && [ "$SESSION_ID" != "$PATHSHALA_ID" ]; then
  echo "  ok    and the session has an id of its own, not the Pathshala's"
  pass=$((pass + 1))
else
  echo "  FAIL  could not read the current session's id (got '$SESSION_ID')"
  fail=$((fail + 1))
fi

CLASS=$(curl -s -X POST "$GATEWAY/v1/pathshala/pathshalas/$PATHSHALA_ID/classes" \
  -H 'Content-Type: application/json' -H "Authorization: Bearer $SAMAAJ_ADMIN_TOKEN" \
  -d "{\"sessionId\":\"$SESSION_ID\",\"name\":\"Class 8 - Jain Studies\",\"roomLabel\":\"Room 2\"}")

CLASS_ID=$(printf '%s' "$CLASS" | json_field id)

if [ -n "$CLASS_ID" ]; then
  echo "  ok    and creates a class in it"
  pass=$((pass + 1))
else
  echo "  FAIL  and creates a class in it"
  fail=$((fail + 1))
fi

check "assigning the member as its teacher" 200 \
  "$(status -X POST "$GATEWAY/v1/pathshala/classes/$CLASS_ID/teachers" \
     -H 'Content-Type: application/json' -H "Authorization: Bearer $SAMAAJ_ADMIN_TOKEN" \
     -d "{\"teacherMemberId\":\"$MEMBER_ID\",\"assign\":true}")"

# Teaching a class is not enough on its own: marking a register needs the
# Pathshala.Attendance.Write permission, which arrives with the
# PathshalaTeacher role. Granting it and signing in again is what proves the
# role actually carries the permission - the check that has caught an
# unreachable permission three times in this repo.
check "granting the member the PathshalaTeacher role" 200 \
  "$(status -X PUT "$GATEWAY/v1/identity/admins/$MEMBER_ID/roles/PathshalaTeacher" \
     -H 'Content-Type: application/json' -H "Authorization: Bearer $ADMIN_TOKEN" \
     -H "$ADMIN_TENANT_HEADER" -d '{"granted":true}')"

TEACHER_TOKEN=$(curl -s -X POST "$GATEWAY/v1/identity/login" -H 'Content-Type: application/json' \
  -d "{\"mobileOrEmail\":\"$MEMBER\",\"password\":\"$MEMBER_PASSWORD\"}" | json_field accessToken)

if [ -n "$TEACHER_TOKEN" ]; then
  echo "  ok    and a fresh token carries the teacher permission"
  pass=$((pass + 1))
else
  echo "  FAIL  could not sign in again after the role grant"
  fail=$((fail + 1))
fi

check "an overlapping timetable slot is refused" 200 \
  "$(status -X POST "$GATEWAY/v1/pathshala/classes/$CLASS_ID/schedule" \
     -H 'Content-Type: application/json' -H "Authorization: Bearer $SAMAAJ_ADMIN_TOKEN" \
     -d '{"dayOfWeek":"Sunday","startTime":"10:00:00","endTime":"12:00:00"}')"

check "and the overlap itself is a conflict" 409 \
  "$(status -X POST "$GATEWAY/v1/pathshala/classes/$CLASS_ID/schedule" \
     -H 'Content-Type: application/json' -H "Authorization: Bearer $SAMAAJ_ADMIN_TOKEN" \
     -d '{"dayOfWeek":"Sunday","startTime":"11:00:00","endTime":"13:00:00"}')"

# ---- Enrolment is two steps ------------------------------------------------

ENROLMENT=$(curl -s -X POST "$GATEWAY/v1/pathshala/pathshalas/$PATHSHALA_ID/enrollments" \
  -H 'Content-Type: application/json' -H "Authorization: Bearer $MEMBER_TOKEN" \
  -d "{\"childProfileId\":\"$CHILD_ID\"}")

ENROLMENT_ID=$(printf '%s' "$ENROLMENT" | json_field id)
require_id enrolment_id "$ENROLMENT_ID"

if printf '%s' "$ENROLMENT" | grep -q '"status":"Requested"'; then
  echo "  ok    a parent asks for a place, and it is not yet a place"
  pass=$((pass + 1))
else
  echo "  FAIL  a parent asks for a place (got '$ENROLMENT')"
  fail=$((fail + 1))
fi

# A parent picking their own child's class is the thing the second step exists
# to prevent - and it is also the only check this service can make that the
# child is theirs.
check "a parent cannot place their own child" 403 \
  "$(status -X POST "$GATEWAY/v1/pathshala/enrollments/$ENROLMENT_ID/placement" \
     -H 'Content-Type: application/json' -H "Authorization: Bearer $MEMBER_TOKEN" \
     -d "{\"classId\":\"$CLASS_ID\",\"place\":true}")"

if curl -s -H "Authorization: Bearer $SAMAAJ_ADMIN_TOKEN" \
   "$GATEWAY/v1/pathshala/pathshalas/$PATHSHALA_ID/enrollments/requests" \
   | grep -q "$ENROLMENT_ID"; then
  echo "  ok    and it reaches the placement queue"
  pass=$((pass + 1))
else
  echo "  FAIL  the request did not reach the placement queue"
  fail=$((fail + 1))
fi

check "the Pathshala places the child in a class" 200 \
  "$(status -X POST "$GATEWAY/v1/pathshala/enrollments/$ENROLMENT_ID/placement" \
     -H 'Content-Type: application/json' -H "Authorization: Bearer $SAMAAJ_ADMIN_TOKEN" \
     -d "{\"classId\":\"$CLASS_ID\",\"place\":true}")"

check "placing an already-placed child is refused" 409 \
  "$(status -X POST "$GATEWAY/v1/pathshala/enrollments/$ENROLMENT_ID/placement" \
     -H 'Content-Type: application/json' -H "Authorization: Bearer $SAMAAJ_ADMIN_TOKEN" \
     -d "{\"classId\":\"$CLASS_ID\",\"place\":true}")"

# ---- The register ----------------------------------------------------------

# The class meets on Sundays, so the register is marked for one that has
# already passed.
CLASS_DATE=$(date -u -d 'last Sunday' +%Y-%m-%d 2>/dev/null || date -u +%Y-%m-%d)

REGISTER="{\"classDate\":\"$CLASS_DATE\",\"marks\":[{\"enrolmentId\":\"$ENROLMENT_ID\",\"status\":\"Present\"}]}"

MARKED=$(curl -s -X POST "$GATEWAY/v1/pathshala/classes/$CLASS_ID/attendance" \
  -H 'Content-Type: application/json' -H "Authorization: Bearer $TEACHER_TOKEN" -d "$REGISTER")

if printf '%s' "$MARKED" | grep -q '"recorded":1'; then
  echo "  ok    the class teacher marks the register"
  pass=$((pass + 1))
else
  echo "  FAIL  the class teacher marks the register (got '$MARKED')"
  fail=$((fail + 1))
fi

# Submitting twice is the ordinary case on a bad connection. The unique index
# on (enrolment, date) is what makes the second one a correction rather than a
# second row.
AGAIN=$(curl -s -X POST "$GATEWAY/v1/pathshala/classes/$CLASS_ID/attendance" \
  -H 'Content-Type: application/json' -H "Authorization: Bearer $TEACHER_TOKEN" \
  -d "{\"classDate\":\"$CLASS_DATE\",\"marks\":[{\"enrolmentId\":\"$ENROLMENT_ID\",\"status\":\"Excused\"}]}")

if printf '%s' "$AGAIN" | grep -q '"amended":1'; then
  echo "  ok    and re-marking corrects rather than duplicating"
  pass=$((pass + 1))
else
  echo "  FAIL  re-marking did not amend (got '$AGAIN')"
  fail=$((fail + 1))
fi

# Reading it back is what makes the amend above safe to offer on a screen:
# anything not re-sent stays as it was, so a form that could not see the
# existing marks would be asking a teacher to remember them.
READ_BACK=$(curl -s -H "Authorization: Bearer $TEACHER_TOKEN" \
  "$GATEWAY/v1/pathshala/classes/$CLASS_ID/register?date=$CLASS_DATE")

if printf '%s' "$READ_BACK" | grep -q '"status":"Excused"'; then
  echo "  ok    and the register reads back with the correction in it"
  pass=$((pass + 1))
else
  echo "  FAIL  the register did not read back (got '$READ_BACK')"
  fail=$((fail + 1))
fi

# Empty, not 404 - a day nobody has marked is a normal state of a register.
EMPTY_DAY=$(curl -s -H "Authorization: Bearer $TEACHER_TOKEN" \
  "$GATEWAY/v1/pathshala/classes/$CLASS_ID/register?date=$(date -u -d '-14 days' +%Y-%m-%d)")

if [ "$EMPTY_DAY" = "[]" ]; then
  echo "  ok    an unmarked date is an empty register rather than an error"
  pass=$((pass + 1))
else
  echo "  FAIL  an unmarked date did not come back empty (got '$EMPTY_DAY')"
  fail=$((fail + 1))
fi

# CHILD_TOKEN, not MEMBER_TOKEN. The member in this script is granted the
# PathshalaTeacher role and assigned to this very class a few checks above, so
# asking them would be asking the teacher - and 200 would be the right answer.
# The same shape of mistake as keying a check on a name the script grants a role
# to further down: the caller changes under the check without the check saying so.
check "a member who does not teach this class cannot read its register" 404 \
  "$(status -H "Authorization: Bearer $CHILD_TOKEN" \
     "$GATEWAY/v1/pathshala/classes/$CLASS_ID/register?date=$CLASS_DATE")"

# The permission gate, before any per-class check: this member is not a
# teacher anywhere.
check "a member with no teacher permission cannot mark it" 403 \
  "$(status -X POST "$GATEWAY/v1/pathshala/classes/$CLASS_ID/attendance" \
     -H 'Content-Type: application/json' -H "Authorization: Bearer $CHILD_TOKEN" -d "$REGISTER")"

check "and a register cannot be marked before the class has met" 409 \
  "$(status -X POST "$GATEWAY/v1/pathshala/classes/$CLASS_ID/attendance" \
     -H 'Content-Type: application/json' -H "Authorization: Bearer $TEACHER_TOKEN" \
     -d "{\"classDate\":\"$(date -u -d '+30 days' +%Y-%m-%d)\",\"marks\":[{\"enrolmentId\":\"$ENROLMENT_ID\",\"status\":\"Present\"}]}")"

# ---- Exams -----------------------------------------------------------------

EXAM=$(curl -s -X POST "$GATEWAY/v1/pathshala/classes/$CLASS_ID/exams" \
  -H 'Content-Type: application/json' -H "Authorization: Bearer $TEACHER_TOKEN" \
  -d "{\"title\":\"Jain History\",\"examDate\":\"$CLASS_DATE\",\"maxScore\":50}")

EXAM_ID=$(printf '%s' "$EXAM" | json_field id)

if [ -n "$EXAM_ID" ]; then
  echo "  ok    the teacher sets an exam"
  pass=$((pass + 1))
else
  echo "  FAIL  the teacher sets an exam"
  fail=$((fail + 1))
fi

check "a score above the paper is refused" 409 \
  "$(status -X POST "$GATEWAY/v1/pathshala/exams/$EXAM_ID/results" \
     -H 'Content-Type: application/json' -H "Authorization: Bearer $TEACHER_TOKEN" \
     -d "{\"enrolmentId\":\"$ENROLMENT_ID\",\"score\":51,\"grade\":null}")"

check "and a mark within it is recorded" 200 \
  "$(status -X POST "$GATEWAY/v1/pathshala/exams/$EXAM_ID/results" \
     -H 'Content-Type: application/json' -H "Authorization: Bearer $TEACHER_TOKEN" \
     -d "{\"enrolmentId\":\"$ENROLMENT_ID\",\"score\":44,\"grade\":\"A\"}")"

# Scheduling answered with an id and nothing listed them again, so an exam set
# last week could not be marked this week by any route the platform offered.
CLASS_EXAMS=$(curl -s -H "Authorization: Bearer $TEACHER_TOKEN" \
  "$GATEWAY/v1/pathshala/classes/$CLASS_ID/exams")

if printf '%s' "$CLASS_EXAMS" | grep -q '"score":44'; then
  echo "  ok    the class lists its exams with the marks already recorded"
  pass=$((pass + 1))
else
  echo "  FAIL  the class exam list did not carry the mark (got '$CLASS_EXAMS')"
  fail=$((fail + 1))
fi

check "and cannot list its exam marks either" 404 \
  "$(status -H "Authorization: Bearer $CHILD_TOKEN" \
     "$GATEWAY/v1/pathshala/classes/$CLASS_ID/exams")"

# ---- What the parent sees --------------------------------------------------

if curl -s -H "Authorization: Bearer $MEMBER_TOKEN" \
   "$GATEWAY/v1/pathshala/enrollments/$ENROLMENT_ID/my-class" | grep -q "Class 8"; then
  echo "  ok    the parent sees the class their child is in"
  pass=$((pass + 1))
else
  echo "  FAIL  the parent cannot see their child's class"
  fail=$((fail + 1))
fi

if curl -s -H "Authorization: Bearer $MEMBER_TOKEN" \
   "$GATEWAY/v1/pathshala/enrollments/$ENROLMENT_ID/progress" | grep -q '"examsSat":1'; then
  echo "  ok    and their progress, computed rather than stored"
  pass=$((pass + 1))
else
  echo "  FAIL  the progress view did not count the exam"
  fail=$((fail + 1))
fi

# Records about somebody's child. Not found rather than forbidden: a 403 would
# confirm which enrolment ids are real.
check "another member cannot read this child's records" 404 \
  "$(status -H "Authorization: Bearer $CHILD_TOKEN" \
     "$GATEWAY/v1/pathshala/enrollments/$ENROLMENT_ID/attendance")"

check "and a class roll is not readable by them either" 404 \
  "$(status -H "Authorization: Bearer $CHILD_TOKEN" \
     "$GATEWAY/v1/pathshala/classes/$CLASS_ID/roll")"

check "while the class teacher may read it" 200 \
  "$(status -H "Authorization: Bearer $TEACHER_TOKEN" \
     "$GATEWAY/v1/pathshala/classes/$CLASS_ID/roll")"

# ---- The module gate -------------------------------------------------------

check "switching the pathshala module off" 200 \
  "$(status -X PUT "$GATEWAY/v1/identity/tenants/$TENANT_ID/modules" \
     -H 'Content-Type: application/json' -H "Authorization: Bearer $ADMIN_TOKEN" \
     -d '{"enabledModules":["community"]}')"

sleep 62

check "the pathshala route answers 404" 404 \
  "$(status -H "Authorization: Bearer $MEMBER_TOKEN" "$GATEWAY/v1/pathshala/pathshalas")"

check "while the timeline, on a different module, is untouched" 200 \
  "$(status -H "Authorization: Bearer $MEMBER_TOKEN" "$GATEWAY/v1/timeline/posts")"

echo
echo "Boli: an occasion, a Boli, a bid, a close, a result, an announcement"

# Wrapped in a function so a missing id can `return` instead of `exit`.
# Aborting the run here would take the three sections after it with it, and
# they have nothing to do with Boli - but carrying on past an id that came
# back empty is how one broken extraction turns into forty checks blaming
# somebody else's service, which is the failure this script already has an
# open item about.
boli_checks() {
  refresh_tokens


  # boli-service had no gateway coverage at all until now, which root CLAUDE.md
  # section 9 asks for on every service - a route that works in isolation but is
  # not wired into the gateway is the failure mode this whole script exists for.
  #
  # SAMAAJ_ADMIN_TOKEN throughout, not ADMIN_TOKEN. The platform Super Admin holds
  # no Samaaj, so a module-gated route refuses their request before it reaches any
  # service - "reached without a resolved Samaaj". Only the two module toggles are
  # theirs, and those carry the override header.
  #
  # This block sits here rather than at the end of the file, which was tried and
  # does not work: by the time the rate-limiting section has finished, MEMBER_TOKEN
  # and ADMIN_TOKEN have expired and eleven checks fail with 401 for a reason that
  # has nothing to do with Boli.
  check "switching the boli module on" 200 \
    "$(status -X PUT "$GATEWAY/v1/identity/tenants/$TENANT_ID/modules" \
       -H 'Content-Type: application/json' -H "Authorization: Bearer $ADMIN_TOKEN" -H "$ADMIN_TENANT_HEADER" \
       -d '{"enabledModules":["community","boli"]}')"

  sleep 62

  OCCASION=$(curl -s -X POST "$GATEWAY/v1/boli/occasions" \
    -H 'Content-Type: application/json' -H "Authorization: Bearer $SAMAAJ_ADMIN_TOKEN" \
    -d '{"title":"Paryushan 2026","description":null,"occasionDate":"2026-09-10"}')

  OCCASION_ID=$(printf '%s' "$OCCASION" | json_field id)

  if [ -n "$OCCASION_ID" ]; then
    echo "  ok    a Samaaj Admin announces an occasion"
    pass=$((pass + 1))
  else
    echo "  FAIL  announcing an occasion (got '$OCCASION')"
    fail=$((fail + 1))
    return 1
  fi

  check "a member cannot announce one" 403 \
    "$(status -X POST "$GATEWAY/v1/boli/occasions" -H 'Content-Type: application/json' \
       -H "Authorization: Bearer $MEMBER_TOKEN" \
       -d '{"title":"Mine","description":null,"occasionDate":"2026-09-10"}')"

  BOLI_TYPE=$(curl -s -X POST "$GATEWAY/v1/boli/occasions/$OCCASION_ID/boli-types" \
    -H 'Content-Type: application/json' -H "Authorization: Bearer $SAMAAJ_ADMIN_TOKEN" \
    -d '{"name":"Mangal Deep","description":null}')

  BOLI_TYPE_ID=$(printf '%s' "$BOLI_TYPE" | json_field id)

  if [ -n "$BOLI_TYPE_ID" ] && [ "$BOLI_TYPE_ID" != "$OCCASION_ID" ]; then
    echo "  ok    and defines a Boli type with an id of its own"
    pass=$((pass + 1))
  else
    echo "  FAIL  the Boli type id is wrong (got '$BOLI_TYPE_ID')"
    fail=$((fail + 1))
    return 1
  fi

  check "the same name twice is refused, whatever the capitalisation" 409 \
    "$(status -X POST "$GATEWAY/v1/boli/occasions/$OCCASION_ID/boli-types" \
       -H 'Content-Type: application/json' -H "Authorization: Bearer $SAMAAJ_ADMIN_TOKEN" \
       -d '{"name":"mangal deep","description":null}')"

  # Amounts are paise. Rs 1,000 floor and a Rs 500 increment.
  BOLI=$(curl -s -X POST "$GATEWAY/v1/boli/occasions/$OCCASION_ID/boli" \
    -H 'Content-Type: application/json' -H "Authorization: Bearer $SAMAAJ_ADMIN_TOKEN" \
    -d "{\"boliTypeId\":\"$BOLI_TYPE_ID\",\"title\":\"Mangal Deep - first day\",
         \"startAt\":\"$(date -u -d '-5 minutes' +%Y-%m-%dT%H:%M:%SZ)\",
         \"endAt\":\"$(date -u -d '+2 hours' +%Y-%m-%dT%H:%M:%SZ)\",
         \"startingAmount\":100000,\"minIncrement\":50000,
         \"eligibilityRule\":\"One per family.\"}")

  BOLI_ID=$(printf '%s' "$BOLI" | json_field id)

  if [ -n "$BOLI_ID" ] && [ "$BOLI_ID" != "$OCCASION_ID" ]; then
    echo "  ok    and opens a Boli against it"
    pass=$((pass + 1))
  else
    echo "  FAIL  opening a Boli (got '$BOLI')"
    fail=$((fail + 1))
    return 1
  fi

  # 200 with accepted:false, not a 409, and this check originally got that
  # wrong. Not clearing the bar is the same case as being outbid - the floor is
  # simply what the bar is before anyone has bid - and boli-service answers both
  # as success carrying the amount now needed. A 409 would be telling a bidder
  # off for offering too little, which is a thing bidders do.
  LOW_BID=$(curl -s -X POST "$GATEWAY/v1/boli/boli/$BOLI_ID/bids" \
    -H 'Content-Type: application/json' -H "Authorization: Bearer $MEMBER_TOKEN" \
    -d '{"amount":50000}')

  if printf '%s' "$LOW_BID" | grep -q '"accepted":false' \
     && printf '%s' "$LOW_BID" | grep -q '"minimumNextBid":100000'; then
    echo "  ok    a bid below the floor is answered with the floor, not refused"
    pass=$((pass + 1))
  else
    echo "  FAIL  a below-floor bid was not answered properly (got '$LOW_BID')"
    fail=$((fail + 1))
  fi

  FIRST_BID=$(curl -s -X POST "$GATEWAY/v1/boli/boli/$BOLI_ID/bids" \
    -H 'Content-Type: application/json' -H "Authorization: Bearer $MEMBER_TOKEN" \
    -d '{"amount":100000}')

  if printf '%s' "$FIRST_BID" | grep -q '"accepted":true'; then
    echo "  ok    a member bids the floor"
    pass=$((pass + 1))
  else
    echo "  FAIL  the first bid was not accepted (got '$FIRST_BID')"
    fail=$((fail + 1))
  fi

  # Being outbid is success with accepted:false, not a 409. Somebody whose form
  # was open while another bid landed has not done anything wrong.
  OUTBID=$(curl -s -X POST "$GATEWAY/v1/boli/boli/$BOLI_ID/bids" \
    -H 'Content-Type: application/json' -H "Authorization: Bearer $CHILD_TOKEN" \
    -d '{"amount":120000}')

  if printf '%s' "$OUTBID" | grep -q '"accepted":false'; then
    echo "  ok    and a bid under the next increment is answered, not refused"
    pass=$((pass + 1))
  else
    echo "  FAIL  an under-increment bid was not reported as unaccepted (got '$OUTBID')"
    fail=$((fail + 1))
  fi

  WINNING=$(curl -s -X POST "$GATEWAY/v1/boli/boli/$BOLI_ID/bids" \
    -H 'Content-Type: application/json' -H "Authorization: Bearer $CHILD_TOKEN" \
    -d '{"amount":150000}')

  if printf '%s' "$WINNING" | grep -q '"accepted":true'; then
    echo "  ok    a clearing bid takes the lead"
    pass=$((pass + 1))
  else
    echo "  FAIL  the clearing bid was not accepted (got '$WINNING')"
    fail=$((fail + 1))
  fi

  # The history is amounts and times. Who bid what, while a Boli is open, turns an
  # auction into a statement about people's means.
  HISTORY=$(curl -s -H "Authorization: Bearer $MEMBER_TOKEN" \
    "$GATEWAY/v1/boli/boli/$BOLI_ID/bids")

  if printf '%s' "$HISTORY" | grep -q '"amount":150000' \
     && ! printf '%s' "$HISTORY" | grep -q 'memberId'; then
    echo "  ok    the bid history carries amounts and never a bidder"
    pass=$((pass + 1))
  else
    echo "  FAIL  the bid history is the wrong shape (got '$HISTORY')"
    fail=$((fail + 1))
  fi

  # Anti-sniping, through the gateway. A second Boli, closing sooner than its
  # own window is long, so a bid placed now is inside the closing window. What
  # is checked here is that the close actually moved - by how much, and that it
  # is measured from the bid rather than from the old close, is the domain
  # suite's job. The pair matters more than either half: the Boli above has no
  # window and must not move, and a bug that extended every Boli would pass the
  # positive check on its own.
  BASE_END=$(printf '%s' "$BOLI" | json_field endAt)

  SNIPE=$(curl -s -X POST "$GATEWAY/v1/boli/occasions/$OCCASION_ID/boli" \
    -H 'Content-Type: application/json' -H "Authorization: Bearer $SAMAAJ_ADMIN_TOKEN" \
    -d "{\"boliTypeId\":\"$BOLI_TYPE_ID\",\"title\":\"Mangal Deep - closing soon\",
         \"startAt\":\"$(date -u -d '-5 minutes' +%Y-%m-%dT%H:%M:%SZ)\",
         \"endAt\":\"$(date -u -d '+90 seconds' +%Y-%m-%dT%H:%M:%SZ)\",
         \"startingAmount\":100000,\"minIncrement\":50000,
         \"eligibilityRule\":null,\"autoExtendSeconds\":300}")

  SNIPE_ID=$(printf '%s' "$SNIPE" | json_field id)
  SNIPE_END=$(printf '%s' "$SNIPE" | json_field endAt)

  if [ -n "$SNIPE_ID" ] && printf '%s' "$SNIPE" | grep -q '"autoExtendSeconds":300'; then
    echo "  ok    a Boli opens with an anti-sniping window"
    pass=$((pass + 1))

    curl -s -o /dev/null -X POST "$GATEWAY/v1/boli/boli/$SNIPE_ID/bids" \
      -H 'Content-Type: application/json' -H "Authorization: Bearer $MEMBER_TOKEN" \
      -d '{"amount":100000}'

    SNIPE_AFTER=$(curl -s -H "Authorization: Bearer $MEMBER_TOKEN" \
      "$GATEWAY/v1/boli/boli/$SNIPE_ID")
    SNIPE_NEW_END=$(printf '%s' "$SNIPE_AFTER" | json_field endAt)

    if [ -n "$SNIPE_NEW_END" ] && [ "$SNIPE_NEW_END" \> "$SNIPE_END" ]; then
      echo "  ok    and a bid in its closing window pushes the close out"
      pass=$((pass + 1))
    else
      echo "  FAIL  a closing bid did not extend the Boli (was '$SNIPE_END', now '$SNIPE_NEW_END')"
      fail=$((fail + 1))
    fi
  else
    echo "  FAIL  opening a Boli with an anti-sniping window (got '$SNIPE')"
    fail=$((fail + 1))
  fi

  PLAIN_AFTER=$(curl -s -H "Authorization: Bearer $MEMBER_TOKEN" \
    "$GATEWAY/v1/boli/boli/$BOLI_ID")
  PLAIN_END=$(printf '%s' "$PLAIN_AFTER" | json_field endAt)

  if [ -n "$BASE_END" ] && [ "$PLAIN_END" = "$BASE_END" ]; then
    echo "  ok    while the Boli without a window closes when it always said"
    pass=$((pass + 1))
  else
    echo "  FAIL  a Boli with no anti-sniping window moved (was '$BASE_END', now '$PLAIN_END')"
    fail=$((fail + 1))
  fi

  check "a result cannot be recorded while bidding is open" 409 \
    "$(status -X POST "$GATEWAY/v1/boli/boli/$BOLI_ID/result" \
       -H "Authorization: Bearer $SAMAAJ_ADMIN_TOKEN")"

  check "the Samaaj Admin closes the Boli" 200 \
    "$(status -X POST "$GATEWAY/v1/boli/boli/$BOLI_ID/close" \
       -H "Authorization: Bearer $SAMAAJ_ADMIN_TOKEN")"

  check "and closing again is safe rather than an error" 200 \
    "$(status -X POST "$GATEWAY/v1/boli/boli/$BOLI_ID/close" \
       -H "Authorization: Bearer $SAMAAJ_ADMIN_TOKEN")"

  RECORDED=$(curl -s -X POST "$GATEWAY/v1/boli/boli/$BOLI_ID/result" \
    -H "Authorization: Bearer $SAMAAJ_ADMIN_TOKEN")

  # The amount is the highest bid, and the winner is absent - for everybody,
  # including the manager who just recorded it.
  if printf '%s' "$RECORDED" | grep -q '"amount":150000' \
     && printf '%s' "$RECORDED" | grep -q '"winningMemberId":null'; then
    echo "  ok    the result is recorded from the highest bid, naming nobody"
    pass=$((pass + 1))
  else
    echo "  FAIL  the recorded result is the wrong shape (got '$RECORDED')"
    fail=$((fail + 1))
  fi

  # The queue that had no endpoint until this cycle: the middle state of a
  # deliberately two-step workflow, which nothing could list.
  PENDING=$(curl -s -H "Authorization: Bearer $SAMAAJ_ADMIN_TOKEN" "$GATEWAY/v1/boli/results/pending")

  if printf '%s' "$PENDING" | grep -q "$BOLI_ID"; then
    echo "  ok    and it appears in the publication queue"
    pass=$((pass + 1))
  else
    echo "  FAIL  the recorded result is not in the queue (got '$PENDING')"
    fail=$((fail + 1))
  fi

  check "which a member may not read" 403 \
    "$(status -H "Authorization: Bearer $MEMBER_TOKEN" "$GATEWAY/v1/boli/results/pending")"

  check "the result is announced" 200 \
    "$(status -X POST "$GATEWAY/v1/boli/boli/$BOLI_ID/result/publish" \
       -H "Authorization: Bearer $SAMAAJ_ADMIN_TOKEN")"

  check "and announcing twice is safe" 200 \
    "$(status -X POST "$GATEWAY/v1/boli/boli/$BOLI_ID/result/publish" \
       -H "Authorization: Bearer $SAMAAJ_ADMIN_TOKEN")"

  PUBLISHED=$(curl -s -H "Authorization: Bearer $MEMBER_TOKEN" \
    "$GATEWAY/v1/boli/boli/$BOLI_ID/result")

  if printf '%s' "$PUBLISHED" | grep -q '"isPublished":true' \
     && ! printf '%s' "$PUBLISHED" | grep -q '"winningMemberId":null'; then
    echo "  ok    only now does the result name its winner"
    pass=$((pass + 1))
  else
    echo "  FAIL  the published result did not name a winner (got '$PUBLISHED')"
    fail=$((fail + 1))
  fi

  AFTER=$(curl -s -H "Authorization: Bearer $SAMAAJ_ADMIN_TOKEN" "$GATEWAY/v1/boli/results/pending")

  if [ "$AFTER" = "[]" ]; then
    echo "  ok    and the queue is empty again"
    pass=$((pass + 1))
  else
    echo "  FAIL  the announced result is still queued (got '$AFTER')"
    fail=$((fail + 1))
  fi

  # A correction after publication is a distinct audited workflow, not a second
  # record.
  check "re-recording after publication is refused" 409 \
    "$(status -X POST "$GATEWAY/v1/boli/boli/$BOLI_ID/result" \
       -H "Authorization: Bearer $SAMAAJ_ADMIN_TOKEN")"

  check "switching the boli module off" 200 \
    "$(status -X PUT "$GATEWAY/v1/identity/tenants/$TENANT_ID/modules" \
       -H 'Content-Type: application/json' -H "Authorization: Bearer $ADMIN_TOKEN" -H "$ADMIN_TENANT_HEADER" \
       -d '{"enabledModules":["community"]}')"

  sleep 62

  check "the boli route then answers 404" 404 \
    "$(status -H "Authorization: Bearer $MEMBER_TOKEN" "$GATEWAY/v1/boli/occasions")"
}

boli_checks || echo "  ..    the rest of the Boli checks were skipped"

# The section above spends two minutes waiting out the module cache twice over.
refresh_tokens

echo
echo "Step-up: taking a Samaaj out of service re-asks for the password"

# On a throwaway Samaaj, not the one the rest of this script is standing on.
# Deactivating that would sign out every member and make every check after this
# point fail for the wrong reason.
DOOMED_SLUG="smoke-doomed-$(date +%s)"

DOOMED_ID=$(curl -s -X POST "$GATEWAY/v1/identity/tenants" \
  -H 'Content-Type: application/json' -H "Authorization: Bearer $ADMIN_TOKEN" \
  -d "{\"name\":\"Doomed Samaaj\",\"slug\":\"$DOOMED_SLUG\",\"enabledModules\":[]}" \
  | json_field id)

if [ -n "$DOOMED_ID" ]; then
  echo "  ok    a throwaway Samaaj to deactivate"
  pass=$((pass + 1))
else
  echo "  FAIL  could not create the throwaway Samaaj"
  fail=$((fail + 1))
fi

check "activating it needs no password" 200 \
  "$(status -X PATCH "$GATEWAY/v1/identity/tenants/$DOOMED_ID/status" \
     -H 'Content-Type: application/json' -H "Authorization: Bearer $ADMIN_TOKEN" \
     -d '{"status":"Active"}')"

check "deactivating it without one is refused" 403 \
  "$(status -X PATCH "$GATEWAY/v1/identity/tenants/$DOOMED_ID/status" \
     -H 'Content-Type: application/json' -H "Authorization: Bearer $ADMIN_TOKEN" \
     -d '{"status":"Inactive"}')"

# Not 401, and this is the point of the whole check. The portals' interceptor
# treats a 401 as an expired access token: it renews the token and retries the
# original request, so a mistyped password would resubmit the deactivation.
WRONG_PASSWORD=$(status -X PATCH "$GATEWAY/v1/identity/tenants/$DOOMED_ID/status" \
  -H 'Content-Type: application/json' -H "Authorization: Bearer $ADMIN_TOKEN" \
  -d '{"status":"Inactive","password":"not-the-password"}')

check "a wrong password is refused" 403 "$WRONG_PASSWORD"

if [ "$WRONG_PASSWORD" != "401" ]; then
  echo "  ok    and never with a 401, which the portals would retry"
  pass=$((pass + 1))
else
  echo "  FAIL  a wrong step-up password answered 401"
  fail=$((fail + 1))
fi

# Refused, so nothing moved.
DOOMED_STATUS=$(curl -s "$GATEWAY/v1/identity/tenants/by-id/$DOOMED_ID" | json_field status)

if [ "$DOOMED_STATUS" = "Active" ]; then
  echo "  ok    and the Samaaj is still serving"
  pass=$((pass + 1))
else
  echo "  FAIL  the Samaaj moved despite the refusal (got '$DOOMED_STATUS')"
  fail=$((fail + 1))
fi

check "the right password goes through" 200 \
  "$(status -X PATCH "$GATEWAY/v1/identity/tenants/$DOOMED_ID/status" \
     -H 'Content-Type: application/json' -H "Authorization: Bearer $ADMIN_TOKEN" \
     -d "{\"status\":\"Inactive\",\"password\":\"$SUPERADMIN_PASSWORD\"}")"

check "archiving asks as well" 403 \
  "$(status -X PATCH "$GATEWAY/v1/identity/tenants/$DOOMED_ID/status" \
     -H 'Content-Type: application/json' -H "Authorization: Bearer $ADMIN_TOKEN" \
     -d '{"status":"Archived"}')"

check "and archives with it" 200 \
  "$(status -X PATCH "$GATEWAY/v1/identity/tenants/$DOOMED_ID/status" \
     -H 'Content-Type: application/json' -H "Authorization: Bearer $ADMIN_TOKEN" \
     -d "{\"status\":\"Archived\",\"password\":\"$SUPERADMIN_PASSWORD\"}")"

# One-way. Checked before the password is asked for, so a request that cannot
# succeed says so rather than first demanding a credential.
check "an archived Samaaj cannot be brought back" 409 \
  "$(status -X PATCH "$GATEWAY/v1/identity/tenants/$DOOMED_ID/status" \
     -H 'Content-Type: application/json' -H "Authorization: Bearer $ADMIN_TOKEN" \
     -d "{\"status\":\"Active\",\"password\":\"$SUPERADMIN_PASSWORD\"}")"

echo
echo "Header forgery"
check "a forged tenant header does not change the answer" 200 \
  "$(status -H "X-Tenant-Id: 11111111-1111-1111-1111-111111111111" \
     -H "Authorization: Bearer $MEMBER_TOKEN" "$GATEWAY/v1/identity/me")"

check "an override from a member is refused" 403 \
  "$(status -H "X-Tenant-Override-Id: $TENANT_ID" \
     -H "Authorization: Bearer $MEMBER_TOKEN" "$GATEWAY/v1/identity/me")"

check "an override from an anonymous caller is refused" 403 \
  "$(status -H "X-Tenant-Override-Id: $TENANT_ID" "$GATEWAY/v1/members")"

echo
echo "Rate limiting"

# The limit is deliberately high - Indian carriers put many subscribers behind
# one address - so this proves the policy is attached and enforcing rather than
# trying to exhaust it. A route with no policy would never answer 429.
RL_STATUS=""
for attempt in $(seq 1 400); do
  code=$(status -X POST "$GATEWAY/v1/identity/login" -H 'Content-Type: application/json' \
    -d '{"mobileOrEmail":"nobody@example.com","password":"wrong"}')
  if [ "$code" = "429" ]; then
    RL_STATUS="429"
    break
  fi
done

if [ "$RL_STATUS" = "429" ]; then
  echo "  ok    sign-in is rate limited per source (429 after $attempt attempts)"
  pass=$((pass + 1))
else
  echo "  FAIL  sign-in was never rate limited in 400 attempts"
  fail=$((fail + 1))
fi

# An authenticated route carries no policy, so the burst above must not have
# taken the rest of the platform down with it.
check "an unrelated route is unaffected by the burst" 200 \
  "$(status -H "Authorization: Bearer $MEMBER_TOKEN" "$GATEWAY/v1/identity/me")"

echo
echo "$pass passed, $fail failed"
[ "$fail" -eq 0 ]
